SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `ab_accbook_info`;

CREATE TABLE `ab_accbook_info` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `AID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '流水表ID',
  `NET_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '网点ID',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位ID',
  `BUS_ORI_TYPE` decimal(6,0) DEFAULT NULL COMMENT '记账业务来源类型',
  `SYS_RACE_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务规则定义(系统业务品种)',
  `IS_BACK` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否可以打回 1可以打回0不可以',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `OPERATOR_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `net_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '网点名称',
  `corp_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据记账信息表';

DROP TABLE IF EXISTS `ab_accrecords`;

CREATE TABLE `ab_accrecords` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '票据流水表id',
  `VID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据主表ID',
  `VVID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据从表id',
  `RECID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据签收表id',
  `TRID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据划拨表ID',
  `LASTID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '上一流水ID',
  `LASTBILLCODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '上一票据状态代码',
  `VALID_SIGN` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '处理标志：0未完成；1可用；2已结束',
  `IS_HIDE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否隐藏1是0否',
  `STATUS` decimal(6,0) DEFAULT NULL COMMENT '审批处理状态：-2已删除；-1打回；0 暂存；10提交；11-94审批中；95 已完成；96已拆包',
  `OPT_STATUS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '操作状态：15待复核；16待发送；17已发送待回应；18已回应待签收；19已签收成功业务完成；-1发送失败；-2打回；-3撤回；-4拒签',
  `SEND_SIGN` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否发送指令标志：0否； 1是 ；',
  `BILL_SOURCE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据来源：10收票登记11背书登记12质押登记14贴现登记15归集收入16上划收入17下拨收入',
  `RETURN_CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '返回代码',
  `RETURN_MSG` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BRIEF_ID` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型',
  `INSIDE_SING` decimal(6,0) DEFAULT NULL COMMENT '内部业务标志：0  否；1 是',
  `ENTER_STOCK_NEW` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '所属库存:10单位库存11中心代管12银行托管',
  `ENTER_STOCK_OLD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '所属库存:10单位库存11中心代管12银行托管',
  `BAIL_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证类型:01开票保证，02承兑保证；03背书保证',
  `RECALL_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '撤回类型',
  `BANKENDRSMTMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '不得转让标记：EM00 可再转让；EM01 不得转让',
  `STTLMMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '清算方式：SM00 开启线上清算、SM01 关闭线上清算',
  `APPLY_DATE` datetime DEFAULT NULL COMMENT '申请日期',
  `BUSINESS_DATE` datetime DEFAULT NULL COMMENT '业务归属日期',
  `RCRSOKMONEY` decimal(15,2) DEFAULT NULL COMMENT '追索同意清偿金额',
  `CN_ACCRECORDS` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '前手',
  `SIGN_UP_FLAG` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'SU00-同意  SU01-拒绝',
  `ABS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '摘要（补录并入库时会判断此 storage 来确定是否入库）',
  `RMK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `CREDIT_CODE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信代码(多个授信用;分开)',
  `BUDGET_CODE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '预算科目(多个科目用;分开)',
  `BAIL_ACC` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金账户',
  `BAILMONEY` decimal(15,2) DEFAULT NULL COMMENT '保证金',
  `BAILPERCENT` decimal(8,6) DEFAULT NULL COMMENT '保证金比例',
  `BAILRATE` decimal(8,6) DEFAULT NULL COMMENT '保证金利率',
  `FEEMONEY` decimal(15,2) DEFAULT NULL COMMENT '手续费',
  `RCRSRSNCD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '追索理由代码:RC00承兑人被依法宣告破产RC01承兑人因违法被责令终止活动（非拒付追索时填写）',
  `RCRS_TP` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '追索种类：RT00 拒付追索；RT01 非拒付追索',
  `SIGNEROK` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款或付款确认人',
  `BIF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行接口代码',
  `ADR` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '保证人地址',
  `REQ_ROLE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人类别RC00接入行RC01企业RC02人民银行RC03被代理行RC04被代理财务公司RC05接入财务公司',
  `REQ_NM` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REQ_CMONID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人组织机构代码',
  `REQ_ACCT_ID` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务发起人账号',
  `REQ_ACCTSVCR` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人开户行号',
  `REQ_ACCTSVCR_AG` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人承接行号',
  `REC_ROLE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人类别：RC00接入行RC01企业RC02人民银行RC03被代理行RC04被代理财务公司RC05接入财务公司',
  `REC_NM` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REC_CMONID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人组织机构代码',
  `REC_ACCT_ID` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收收人账号',
  `REC_ACCTSVCR` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人开户行号',
  `REC_ACCTSVCR_AG` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人承接行号',
  `BUS_GLOBAL_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '全局业务ID',
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件ID',
  `CDT_RATGS` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '信用等级',
  `CDT_RATG_AGCY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评级机构',
  `CDT_RATG_DUEDT` datetime DEFAULT NULL COMMENT '评级到期日',
  `EMIT_STTLMMK` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '应付票据兑付方式：0或空线下兑付1线上兑付',
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人名称',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人名称',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `BILL_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外围系统票据ID',
  `MSG_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发送指令消息ID',
  `TRADER` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RSN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_AUTOSIGN` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_HANDLING` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否需要经办 0或空 否  1是',
  `SERIAL_NO` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '流水号',
  `IS_ENDORSE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否同意背书',
  `bill_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款通知单单号',
  `billhead_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款通知单ID',
  `payer_acc` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款账号',
  `payer_acc_bank_type_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款账号银行类型',
  `req_bank_acc_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '银行账户ID',
  `COPY_FLAG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '是否是复制而来的流水，用于标志拆票时复制出来的流水。0否1是，默认0否',
  `COPY_ACC_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '当COPY_FLAG为1是，此字段为被复制的流水id，COPY_FLAG为0时为空',
  `REQ_SOC_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人统一社会信用代码',
  `REC_SOC_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人统一社会信用代码',
  `REC_DGH_TYPE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人识别类型。DT01 票据账户DT02 银行账户默认为DT02 “银行账户”',
  `SETTLEDATE` datetime DEFAULT NULL COMMENT '结息日期',
  `LAST_CIRCULATE_CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据上一票据流通状态',
  `SPLIT_FLG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '此笔交易是否拆分，1是，其他为未拆',
  `OLD_ACC_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记录拆分前的流水id，若是未拆分为空',
  `LAST_BL_BSN_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '上一票据业务代码',
  `SETTLETYPE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '清算类型：CT01 全额清算，CT02净额清算，默全额清算',
  `FEEMONEY_SCALE` decimal(8,6) DEFAULT NULL COMMENT '手续费比例',
  `EXC_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指令id',
  `INSIDE_ENDORSE_AUTO_REG_SIGN` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '对内背书线上背给线下自动登记标志：1-已登记 0-未登记',
  `BATCH_DTL_NO` decimal(6,0) DEFAULT NULL,
  `final_approver` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_AC_RECORDS_UNION` (`VALID_SIGN`,`LASTID`,`OPT_STATUS`,`BRIEF_ID`) USING BTREE,
  KEY `IDX_AC_RECORDS_RECID` (`RECID`) USING BTREE,
  KEY `IDX_AC_RECORDS_VID` (`VID`) USING BTREE,
  KEY `IDX_AB_ACCRECORDS_LASTID_OPT_BRIEF` (`LASTID`,`OPT_STATUS`,`BRIEF_ID`) USING BTREE,
  KEY `IDX_AC_RECORDS_VVID` (`VVID`) USING BTREE,
  KEY `IDX_AB_ACCRECORDS_VVID_BRIEF_SIGN` (`VVID`,`SEND_SIGN`,`BIF_CODE`,`BRIEF_ID`) USING BTREE,
  KEY `AB_ACCRECORDS_LASTID_IDX` (`LASTID`),
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据流水表';

DROP TABLE IF EXISTS `ab_accrecords_his`;

CREATE TABLE `ab_accrecords_his` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `VID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VVID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RECID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TRID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `LASTID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `LASTBILLCODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VALID_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_HIDE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `STATUS` decimal(6,0) DEFAULT NULL,
  `OPT_STATUS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SEND_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BILL_SOURCE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RETURN_CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RETURN_MSG` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BRIEF_ID` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `INSIDE_SING` decimal(6,0) DEFAULT NULL,
  `ENTER_STOCK_NEW` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ENTER_STOCK_OLD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BAIL_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RECALL_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANKENDRSMTMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `STTLMMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `APPLY_DATE` datetime DEFAULT NULL,
  `BUSINESS_DATE` datetime DEFAULT NULL,
  `RCRSOKMONEY` decimal(15,2) DEFAULT NULL,
  `CN_ACCRECORDS` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SIGN_UP_FLAG` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ABS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RMK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREDIT_CODE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BUDGET_CODE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BAIL_ACC` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BAILMONEY` decimal(15,2) DEFAULT NULL,
  `BAILPERCENT` decimal(8,6) DEFAULT NULL,
  `BAILRATE` decimal(8,6) DEFAULT NULL,
  `FEEMONEY` decimal(15,2) DEFAULT NULL,
  `RCRSRSNCD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RCRS_TP` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SIGNEROK` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BIF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ADR` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REQ_ROLE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REQ_NM` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REQ_CMONID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REQ_ACCT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REQ_ACCTSVCR` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REQ_ACCTSVCR_AG` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REC_ROLE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REC_NM` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REC_CMONID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REC_ACCT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REC_ACCTSVCR` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REC_ACCTSVCR_AG` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BUS_GLOBAL_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CDT_RATGS` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CDT_RATG_AGCY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CDT_RATG_DUEDT` datetime DEFAULT NULL,
  `EMIT_STTLMMK` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime(6) DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime(6) DEFAULT NULL,
  `BILL_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `MSG_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TRADER` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RSN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_AUTOSIGN` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `ab_add_credit_info`;

CREATE TABLE `ab_add_credit_info` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `VID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TYPE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BL_UNN_ID_NO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `GRA_ADDRESS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BILL_ACC_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHANNEL_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BILL_ACC_NO` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_NO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_ACC_NO` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `ab_backbillinfo`;

CREATE TABLE `ab_backbillinfo` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '票据背面信息表id',
  `RPDMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贴现种类：RM00 买断式；RM01 回购式',
  `BUSSDT` datetime DEFAULT NULL COMMENT '业务完成日期',
  `INTRSTRATE` decimal(8,6) DEFAULT NULL COMMENT '贴现利率',
  `AMT` decimal(14,2) DEFAULT NULL COMMENT '贴现金额',
  `AOACCNINF_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '入账账号',
  `AOACCNINF_AC` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '入账账号行号',
  `BANKENDRSMTMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '不得转让标记：EM00 可再转让；EM01 得转让',
  `STTLMMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '线上清算标记：SM00 开启线上清算；SM01 关闭线上清算',
  `RPDOPENDT` datetime DEFAULT NULL COMMENT '赎回开放日',
  `RPDDUEDT` datetime DEFAULT NULL COMMENT '赎回截止日',
  `RPDINTRSTRATE` decimal(8,6) DEFAULT NULL COMMENT '申请赎回利率',
  `RPDAMT` decimal(14,2) DEFAULT NULL COMMENT '赎回金额',
  `TXLCTRCTNB` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '交易合同编号',
  `INVCNB` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发票号码',
  `APPLDT` datetime DEFAULT NULL COMMENT '追索通知日期',
  `RSN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原因说明',
  `RCRS_TP` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '追索种类：RT00 拒付追索；RT01 非拒付追索',
  `REQAMT` decimal(14,2) DEFAULT NULL COMMENT '追索金额',
  `RCRSRSNCD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '追索理由代码：RC00 承兑人被依法宣告破产；RC01 承兑人因违法被责令终止活动（非拒付追索时填写）',
  `MSGID` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '报文id',
  `MSDT` datetime DEFAULT NULL COMMENT '报文时间',
  `BUSTYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型：002承兑003收票010背书011贴现012贴现赎回013转贴现014转贴现赎回015再贴现016再贴现赎回017保证018质押019解除质押020提示付款021逾期提示付款022追索025央行卖票',
  `ORIG_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据号码',
  `REQ_ROLE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人类别',
  `REQ_NM` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REQ_CMONID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人组织机构代码',
  `REQ_ACCT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人账号',
  `REQ_ACCTSVCR` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人开户行号',
  `REQ_ACCTSVCR_AG` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人承接行号',
  `BTCHNB` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '批次号',
  `REC_ROLE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人类别',
  `REC_NM` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REC_CMONID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人组织机构代码',
  `REC_ACCT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人账号',
  `REC_ACCTSVCR` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人开户行号',
  `REC_ACCTSVCR_AG` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人承接行号',
  `CDTRATGS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '信用等级',
  `CDTRATGAGCY` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评级机构',
  `CDTRATGDUEDT` datetime DEFAULT NULL COMMENT '评级到期日',
  `ADR` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '保证人地址',
  `UCONDLPRMSMRK` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '到期无条件支付承诺',
  `ACCPTNCAGRMTNB` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑协议编号',
  `DPTYMK` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否代客户回复',
  `DSHNRCD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '拒付理由代码',
  `DSHNRRSN` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '拒付理由备注',
  `SGNUPMK` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '回复标记：SU00:同意签收；SU01：拒收',
  `UCONDLCONSGNMTMRK` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '到期无条件支付委托:提示承兑专用 CC00含委托/承诺兑付',
  `DSCNTAGRMTNB` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贴现协议编号',
  `RMRKBYPROPSR` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '回复人备注',
  `RMRKBYSGNR` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '申请人备注',
  `PRXYSGNTR` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '代理回复标识',
  `BLGRDBAGCRCL_PRMT_IND` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '否允许分包。1 是  0 否，默认为否  新系统出票标志为"0"(老系统出 票) 时，只能填写"0"(不可分包流 转)',
  `SBBLL_RNG_STRT_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间开始序号',
  `SBBLL_RNG_END_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间结束序号',
  `BL_REQ_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人统一社会信用代码',
  `BL_RCV_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人统一社会信用代码',
  `BL_REQ_ID_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人识别类型。DT01 票据账户DT02 银行账户  暂时固定为“银行账户”。旧票据可无',
  `BL_RCV_ID_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收识别类型。DT01 票据账户DT02 银行账户  暂时固定为“银行账户”。旧票据可无',
  `INTPYMTPRT_WAY` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息方式， 1 卖方2 买方3 协议4 他方付息',
  `BUYERPAYINTRCNTNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '买方付息合作协议编号',
  `INTPYMT_PSN_NM` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息人名称',
  `INTPYMT_PSN_ACCNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息人账号',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='记录票据背面信息';

DROP TABLE IF EXISTS `ab_bill_acc_bal`;

CREATE TABLE `ab_bill_acc_bal` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键ID',
  `BANK_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行账户ID',
  `BANK_ACC` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行账号',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位ID',
  `CUR_ID` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别ID',
  `BAL_DATE` datetime DEFAULT NULL COMMENT '余额日期',
  `BAL` decimal(19,2) DEFAULT NULL COMMENT '余额',
  `AVAIL_BAL` decimal(19,2) DEFAULT NULL COMMENT '可用余额',
  `TIEDUP_BAL` decimal(19,2) DEFAULT NULL COMMENT '占用金额',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `SP_BAL` decimal(19,2) DEFAULT NULL,
  `SP_AVAIL_BAL` decimal(19,2) DEFAULT NULL,
  `SP_TIEDUP_BAL` decimal(19,2) DEFAULT NULL,
  `YP_BAL` decimal(19,2) DEFAULT NULL,
  `YP_AVAIL_BAL` decimal(19,2) DEFAULT NULL,
  `YP_TIEDUP_BAL` decimal(19,2) DEFAULT NULL,
  `CORP_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位CODE',
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据账户余额';

DROP TABLE IF EXISTS `ab_bill_acc_dtl`;

CREATE TABLE `ab_bill_acc_dtl` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键ID',
  `RECORD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据流水表ID',
  `TRANS_TIME` datetime DEFAULT NULL COMMENT '交易时间',
  `THAW_TIME` datetime DEFAULT NULL COMMENT '解冻时间',
  `MONEY` decimal(19,2) DEFAULT NULL COMMENT '交易金额',
  `CD_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '流水标志0借1贷2冻结',
  `VALID_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '有效标记0无效1有效',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人ID',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人ID',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据账户余额明细表';

DROP TABLE IF EXISTS `ab_bill_attachment`;

CREATE TABLE `ab_bill_attachment` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '表ID',
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件ID',
  `NUM` decimal(6,0) DEFAULT NULL COMMENT '附件数量',
  `VVID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据从表id',
  `ACID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '流水ID',
  `BRIEF_ID` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型',
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人名称',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人名称',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据附件信息表';

DROP TABLE IF EXISTS `ab_bill_bank_auto_dtl`;

CREATE TABLE `ab_bill_bank_auto_dtl` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '唯一ID',
  `BIF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行接口代码ID',
  `AUTO_ACCEPT` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '提示承兑（0否； 1是 ）',
  `AUTO_INVOICE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '提示收票（0否； 1是 ）',
  `AUTO_PAY` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '提示付款（0否； 1是 ）',
  `VALID_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否有效（0否； 1是 ）',
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人名称',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人名称',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `POOL_ENDORSE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '1',
  `POOL_EMITBILL` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0' COMMENT '票据池开票（0否; 1是 ） ',
  `type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '银行类别名称',
  `bank_type` char(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '银行类型编码',
  `bank_type_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '银行类别编码',
  `bif_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '接口代码名称',
  `bif_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '接口代码ID',
  `NEW_BILL_FLG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否支持新一代票据，1支持，其他不支持',
  `NEW_BIF_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '银行接口代码ID(更正bifId和bifCod并后期使用)',
  `NEW_BIF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '银行接口代码(更正bifId和bifCod并后期使用)',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据银行自动业务配置';

DROP TABLE IF EXISTS `ab_bill_credit_info_maintain`;

CREATE TABLE `ab_bill_credit_info_maintain` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位id',
  `BANK_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型',
  `CREDIT_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信类型：敞口和低风险',
  `BOND_RATIO` decimal(18,2) DEFAULT NULL COMMENT '保证金比例',
  `OPEN_BILL_RATE` decimal(18,2) DEFAULT NULL COMMENT '开票手续费',
  `BOND_RATE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金利率',
  `IS_USED` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否能正常使用：1-是，0-否',
  `IS_DELETED` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='银行开票授信资料维护表';

DROP TABLE IF EXISTS `ab_bill_middle`;

CREATE TABLE `ab_bill_middle` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '表ID',
  `BU_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务ID',
  `TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '中间表类型:1票据签收消息提醒2 票据到期提醒3 到期拒付消息提醒4 收到待清偿数据提醒5 票据到期未兑付提醒6 线上电票提示收票完成补录提醒',
  `VALID_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '处理标志：0不可用；1可用',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据中间表';

DROP TABLE IF EXISTS `ab_bill_pay_middle`;

CREATE TABLE `ab_bill_pay_middle` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `PAY_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款单id',
  `BILL_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据从表id',
  `BALANCE` decimal(15,2) DEFAULT NULL COMMENT '挂接付款余额',
  `PAY_MONEY` decimal(15,2) DEFAULT NULL COMMENT '本次付款金额',
  `STATUS` decimal(2,0) DEFAULT NULL COMMENT '状态',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BILL_PAY_UNION` (`PAY_ID`,`STATUS`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据付款中间表';

DROP TABLE IF EXISTS `ab_bill_plan_amt_maintain`;

CREATE TABLE `ab_bill_plan_amt_maintain` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位id',
  `BANK_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型',
  `CREDIT_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信类型：敞口和低风险',
  `WEEK_START_DAY` date DEFAULT NULL COMMENT '周开始日',
  `WEEK_END_DAY` date DEFAULT NULL COMMENT '周结束日',
  `CURR_WEEK_BILL_MONEY` decimal(18,2) DEFAULT NULL COMMENT '本周计划开票金额',
  `NEXT_WEEK_BILL_MONEY` decimal(18,2) DEFAULT NULL COMMENT '下周计划开票金额',
  `IS_DELETED` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='银行计划开票金额维护表';

DROP TABLE IF EXISTS `ab_bill_receivebiz`;

CREATE TABLE `ab_bill_receivebiz` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '票据签收表id',
  `MSGID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '报文id',
  `MSDT` datetime DEFAULT NULL COMMENT '报文时间',
  `ORGNLMSGID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原申请报文id',
  `ORGNLMSDT` datetime DEFAULT NULL COMMENT '原申请报文时间',
  `MSGTYPE` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '报文编号：017提示保证002提示承兑003提示收票010背书申请012回购式贴现赎回018质押申请019质押解除020提示付款021逾期付款022追索通知023追索同意清偿',
  `ORIG_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据号码',
  `BILL_TYPE` decimal(6,0) DEFAULT NULL COMMENT '票据种类：10 银票；11 商票',
  `START_DATE` datetime DEFAULT NULL COMMENT '起始日期',
  `END_DATE` datetime DEFAULT NULL COMMENT '到期日期',
  `BILL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '票据金额',
  `BILL_STATUS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据状态：参照人行标准格式的81个业务状态编号',
  `PAYEE` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人',
  `PAYEEACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人账号',
  `PAYEEBANKNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人开户行号',
  `PAYER` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人',
  `PAYERACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人账号',
  `PAYERBANKNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人开户行行号',
  `ACCEPTOR` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人',
  `ACCEPTORACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人账号',
  `ACCEPTORBANKNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人行户行行号',
  `CDTRATGS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '信用等级',
  `CDTRATGAGCY` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评级机构',
  `CDTRATGDUEDT` datetime DEFAULT NULL COMMENT '评级到期日',
  `BUSSDT` datetime DEFAULT NULL COMMENT '业务申请日期',
  `ACCPTNCAGRMTNB` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑协议编号',
  `TXLCTRCTNB` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '交易合同编号',
  `INVCNB` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发票号码',
  `ACCEPTORDATE` datetime DEFAULT NULL COMMENT '承兑日期',
  `UCONDLPRMSMRK` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '到期无条件支付承诺 承兑回复必填 CC00含委托/承诺兑付',
  `STTLMMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '线上清算标记： SM00 开启线上清算；SM01 关闭线上清算',
  `BANKENDRSMTMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '不得转让标记：EM00 可再转让；EM01 不得转让',
  `RPDMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贴现种类：RM00 买断式；RM01 回购式',
  `INTRSTRATE` decimal(8,6) DEFAULT NULL COMMENT '贴现利率',
  `AMT` decimal(15,2) DEFAULT NULL COMMENT '贴现金额',
  `AOACCNINF_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '入账账号',
  `AOACCNINF_AC` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '入账账号行号',
  `RPDOPENDT` datetime DEFAULT NULL COMMENT '赎回开放日',
  `RPDDUEDT` datetime DEFAULT NULL COMMENT '赎回截止日',
  `RPDINTRSTRATE` decimal(8,6) DEFAULT NULL COMMENT '申请赎回利率',
  `RPDAMT` decimal(15,2) DEFAULT NULL COMMENT '赎回金额',
  `BUYER_INTEREST_SIGN` decimal(1,0) DEFAULT NULL COMMENT '买方付息标志',
  `BUYER_INTEREST_UNIT` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '买方付息单位',
  `BUYER_INTEREST_ACCOUNT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '买方付息账号',
  `RMRKBYPROPSR` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '贴出人备注',
  `APPLDT` datetime DEFAULT NULL COMMENT '追索通知日期',
  `RSN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原因说明',
  `RCRS_TP` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '追索种类：RT00 拒付追索；RT01 非拒付追索',
  `REQAMT` decimal(15,2) DEFAULT NULL COMMENT '追索金额',
  `RCRSRSNCD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '追索理由代码:RC00承兑人被依法宣告破产RC01承兑人因违法被责令终止活动（非拒付追索时填写）',
  `RCRSOKMONEY` decimal(15,2) DEFAULT NULL COMMENT '追索同意清偿金额',
  `ADR` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证人地址',
  `REQ_ROLE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人类别RC00接入行RC01企业RC02人民银行RC03被代理行RC04被代理财务公司RC05接入财务公司',
  `REQ_NM` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务发起人',
  `REQ_CMONID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人组织机构代码',
  `REQ_ACCT_ID` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务发起人账号',
  `REQ_ACCTSVCR` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人开户行号',
  `REQ_ACCTSVCR_AG` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人承接行号',
  `ELCTRNCSGNTR` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '业务申请人电子签名',
  `BTCHNB` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '批次号',
  `REC_ROLE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人类别：RC00接入行RC01企业RC02人民银行RC03被代理行RC04被代理财务公司RC05接入财务公司',
  `REC_NM` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人',
  `REC_CMONID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人组织机构代码',
  `REC_ACCT_ID` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人账号',
  `REC_ACCTSVCR` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人开户行号',
  `REC_ACCTSVCR_AG` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人承接行号',
  `REC_CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人单位ID',
  `REPLY_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '回复类别',
  `REPLY_DT` datetime DEFAULT NULL COMMENT '回复日期',
  `SGNUPMK` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '回复标志SU00同意签收SU01拒绝签收',
  `SIGN_UP_FLAG` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '签收标识：SU00 通用回复同意；SU01 通用回复拒绝 ',
  `DSHNRCD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '拒付理由代码：DC00与自己有直接债权债务关系的持票人未履行约定义务；DC01持票人以欺诈、偷盗或者胁迫等手段取得票据；DC02持票人明知有欺诈、偷盗或者胁迫等情形，出于恶意取得票据；DC03持票人明知债务人与出票人或者持票人的前手之间存在抗辩事由而取得票据；DC04持票人因重大过失取得不符合《票据法》规定的票据；DC05超过提示付款期；DC06被法院冻结或收到法院止付通知书；DC07票据未到期；DC08商业承兑汇票承兑人账户余额不足。DC09其他（必须注明）',
  `DSHNRRSN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '拒付理由备注',
  `STATUS` decimal(6,0) DEFAULT NULL COMMENT '处理状态：18待签收19签成功-2打回-3撤回',
  `RMK` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '备注',
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人名称',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人名称',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `BILL_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外围系统票据ID',
  `PAYER_BANK_NAME` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人开户银行名称',
  `ACCEPTOR_BANK_NAME` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SERIAL_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '标识号',
  `REC_ACCT_TYPE_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人账号银行类型',
  `REC_CORP_CODE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人单位CODE',
  `REC_CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人单位名称',
  `NEW_STM_ISSUOFPPR_IND` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '出票标志。0：老系统出票,   1：新系统出票',
  `BLGRDBAGCRCL_PRMT_IND` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '是否允许分包。1 是  0 否，默认为否  新系统出票标志为"0"(老系统出 票) 时，只能填写"0"(不可分包流 转)',
  `SBBLL_RNG_STRT_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间开始序号。旧票据默认0，新票据 12位长度，不足12位前面补0',
  `SBBLL_RNG_END_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间结束序号。旧票据默认0，新票据 12位长度，不足12位前面补0',
  `BL_RMTR_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人统一社会信用代码。旧票据可无，新票据需展示',
  `BL_ACPTR_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人统一社会信用代码。旧票据可无，新票据需展示',
  `BL_RCVPYMTPS_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人统一社会信用代码。旧票据可无，新票据需展示',
  `BL_REQ_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人统一社会信用代码。旧票据可无，新票据需展示',
  `BL_RCV_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务接收人统一社会信用代码。旧票据可无，新票据需展示',
  `BL_ACPTR_ID_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人识别类型。DT01 票据账户DT02 银行账户  暂时固定为“银行账户”。旧票据可无',
  `BL_RCVPYMTPS_ID_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人人识别类型。DT01 票据账户DT02 银行账户  暂时固定为“银行账户”。旧票据可无',
  `BL_REQ_ID_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人识别类型。DT01 票据账户DT02 银行账户  暂时固定为“银行账户”。旧票据可无',
  `BL_RCV_ID_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务申请人识别类型。DT01 票据账户DT02 银行账户  暂时固定为“银行账户”。旧票据可无',
  `EBILL_BL_CRCL_INDCD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据流通标',
  `INTPYMTPRT_WAY` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息方式， 1 卖方2 买方3 协议4 他方付息',
  `BUYERPAYINTRCNTNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '买方付息合作协议编号',
  `INTPYMT_PSN_NM` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息人名称',
  `INTPYMT_PSN_ACCNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息人账号',
  `REC_BANK_TYPE_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接收人银行类型id',
  `REPEAT_REC_SIGN` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BILL_RECEIVEBIZ_ORIGNOSBBLNO` (`ORIG_NO`,`SBBLL_RNG_STRT_SN`) USING BTREE,
  KEY `IDX_BILL_RECEIVEBIZ_ORIGNOSBBLNO2` (`ORIG_NO`,`SBBLL_RNG_STRT_SN`,`SBBLL_RNG_END_SN`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='电票签收表';

DROP TABLE IF EXISTS `ab_bill_rulebilldtlrmk`;

CREATE TABLE `ab_bill_rulebilldtlrmk` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `BANK_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型ID',
  `BANK_TYPE_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型名称',
  `BUSTYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型：001托收,002贴现,003兑付',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态 0无效,1有效',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`),
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='票据流水备注规则表';

DROP TABLE IF EXISTS `ab_bill_rulebilldtlrmk_dtl`;

CREATE TABLE `ab_bill_rulebilldtlrmk_dtl` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `BUS_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主表规则业务ID',
  `MATCH_RULE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '匹配规则  01-或者  02-并且',
  `MATCH_ELEMENTS` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '匹配要素 remark-摘要、bankAcc-本方账户、accName-本方账户名、oppAccNo-对方账户、oppAccName-对方账户名、curId-币别、corpId-单位名称、uses-用途、postscript-附言、amt-金额',
  `MATCH_RELATIONS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '匹配关系 1-包含、2-不包含、3-等于、4-不等于',
  `MATCH_CONTENT` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '匹配内容',
  `SORT` int DEFAULT NULL COMMENT '排序',
  `LEFT_PARENTHESIS` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '左括号',
  `RIGHT_PARENTHESIS` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '右括号',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`),
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='票据流水备注规则明细表';

DROP TABLE IF EXISTS `ab_bill_rulebillno`;

CREATE TABLE `ab_bill_rulebillno` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `bank_type_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BUSTYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BILL_NUMBER_FIELD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RELATION_MATCHING` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BILLNO_SEPARATED` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VALID_MARK` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `bank_type_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型',
  `IS_SUMMARY_CLAIM_BILL` varchar(10) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否汇总认领流水 0-否 1-是',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `ab_bill_sign_strategy`;

CREATE TABLE `ab_bill_sign_strategy` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BEGIN_NUM` decimal(15,2) DEFAULT NULL,
  `END_NUM` decimal(15,2) DEFAULT NULL,
  `BEGIN_OPERATOR` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `END_OPERATOR` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NUM_OPERATOR` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BILL_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SIGN_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANKENDRSMTMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VALID_SIGN` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `UPDATE_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `CORP_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '单位编号',
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '单位名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `ab_bill_sign_strategy_data`;

CREATE TABLE `ab_bill_sign_strategy_data` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `SS_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `DATA_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ORG_TAG` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `DATA_VAL` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `ab_bill_status`;

CREATE TABLE `ab_bill_status` (
  `ID` decimal(6,0) NOT NULL COMMENT '序号',
  `STATUSNAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据状态名称',
  `STATUS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '状态码',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据主状态表';

DROP TABLE IF EXISTS `ab_bill_transfer`;

CREATE TABLE `ab_bill_transfer` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `ALLOCATED_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单号',
  `ALLOCATION_MONEY` decimal(15,2) DEFAULT NULL COMMENT '金额',
  `ALLOCATION_REASON` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原因',
  `RECORD_CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '录入单位ID',
  `RECORD_CORP_NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '录入单位名称',
  `RECORD_DATE` datetime DEFAULT NULL COMMENT '录入日期',
  `RECEVIE_CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票单位ID',
  `RECEVIE_CORP_NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票单位名称',
  `BILL_CURRENCY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据币别',
  `ENCLOSURE` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件',
  `RECEVIE_BANKACC` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票单位账号',
  `RECORD_BANKACC` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '下拨中心账号',
  `CREATE_NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人名称',
  `CREATE_BY` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人名称',
  `UPDATE_BY` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `RECORD_CORP_CODE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '录入单位CODE(冗余)',
  `RECEVIE_CORP_CODE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票单位code(冗余)',
  `BILL_CUR_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据币别名称（冗余）',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据上划下拨表';

DROP TABLE IF EXISTS `ab_bill_transfer_dtl`;

CREATE TABLE `ab_bill_transfer_dtl` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `TRANSFER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '下拨表ID',
  `BILL_AID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据流水ID',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='下拨流水和票据流水关系表';

DROP TABLE IF EXISTS `ab_claim_account`;

CREATE TABLE `ab_claim_account` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BUS_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VALID_SIGN` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位名称',
  `BANK_TYPE_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `ab_claim_middle`;

CREATE TABLE `ab_claim_middle` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `claim_sequence` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '认领序列',
  `claim_person` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '认领人',
  `claim_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '认领状态',
  `claim_time` datetime DEFAULT NULL COMMENT '认领时间',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人名称',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `create_date` datetime DEFAULT NULL COMMENT '创建日期',
  `update_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人名称',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `update_date` datetime DEFAULT NULL COMMENT '更新日期',
  `rmk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `orig_no` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据号码',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据认领中间表';

DROP TABLE IF EXISTS `ab_creditinfo_response`;

CREATE TABLE `ab_creditinfo_response` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `MSGID` varchar(35) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '报文ID',
  `CREDTTM` datetime DEFAULT NULL COMMENT '报文返回时间',
  `PREMSGID` varchar(35) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PRECREDTTM` datetime DEFAULT NULL,
  `NM` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '机构名称',
  `CMONID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '被查人组机构代码',
  `ACCPTDQTY` decimal(65,30) DEFAULT NULL COMMENT '承兑票据总笔数',
  `ACCPTDAMT` decimal(15,2) DEFAULT NULL COMMENT '承兑票据总金额',
  `PYDQTY` decimal(65,30) DEFAULT NULL COMMENT '结清票据总笔数',
  `PYDAMT` decimal(15,2) DEFAULT NULL COMMENT '结清票据总金额',
  `PDGQTY` decimal(65,30) DEFAULT NULL COMMENT '未结清票据总笔数',
  `PDGAMT` decimal(15,2) DEFAULT NULL COMMENT '未结清票据总金额',
  `DSHNRQTY` decimal(65,30) DEFAULT NULL COMMENT 'DSHNRQTY',
  `DSHNRAMT` decimal(15,2) DEFAULT NULL COMMENT '拒付票据总金额',
  `DSHNRQTYSNCTHSYR` decimal(65,30) DEFAULT NULL COMMENT '今年拒付总笔数',
  `DSHNRAMTSNCTHSYR` decimal(15,2) DEFAULT NULL COMMENT '今年拒付总金额',
  `DSHNRQTYSNCLASTYR` decimal(65,30) DEFAULT NULL COMMENT '去年拒付总笔数',
  `DSHNRAMTSNCLASTYR` decimal(15,2) DEFAULT NULL COMMENT '去年拒付总金额',
  `ENTERDATE` datetime DEFAULT NULL COMMENT '创建时间',
  `BILL_CODE` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据号码',
  `SBBLL_RNG_STRT_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间开始序号',
  `SBBLL_RNG_END_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间结束序号',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='支付信用表';

DROP TABLE IF EXISTS `ab_discount`;

CREATE TABLE `ab_discount` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '贴现id',
  `RECORD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据流水表id',
  `DISCOUNT_DATE` datetime DEFAULT NULL COMMENT '贴现日期',
  `DAYNUM` decimal(8,0) DEFAULT NULL COMMENT '贴现天数',
  `INTEREST` decimal(15,2) DEFAULT NULL COMMENT '贴现利息',
  `RPDMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贴现种类：RM00 买断式、RM01 回购式买断式',
  `BUYERINTEREST_SING` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否买方付息：10 是、11 否',
  `BUYERINTEREST_RATIO` decimal(8,6) DEFAULT NULL COMMENT '买方付息比率',
  `BUYERINTEREST_MONEY` decimal(15,2) DEFAULT NULL COMMENT '买方付息金额',
  `REAL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '实付金额',
  `STTLMMK` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '清算方式：SM00 开启线上清算、SM01 关闭线上清算',
  `PAYDATE` decimal(8,0) DEFAULT NULL COMMENT '划款天数',
  `DEFERDATE` decimal(8,0) DEFAULT NULL COMMENT '假期顺延天数',
  `INTEREST_RATES` decimal(8,6) DEFAULT NULL COMMENT '贴现利率',
  `AOACCNINF_ID` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '入账账户',
  `AOACCNINF_AC` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '入账行号',
  `RPDOPENDT` datetime DEFAULT NULL COMMENT '赎回开放日',
  `RPDDUEDT` datetime DEFAULT NULL COMMENT '赎回截止日',
  `TXL_CTRCT_NB` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '交易合同编号',
  `INVC_NB` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发票号码',
  `OCCUPANCY_RATIO` decimal(15,2) DEFAULT NULL,
  `RPDINTRSTRATE` decimal(8,6) DEFAULT NULL,
  `BANK_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '入账行名称',
  `AOACCNINF_BANK_TYPE_ID` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '入账银行类型',
  `INTPYMTPRT_WAY` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息方式， 1 卖方2 买方3 协议4 他方付息',
  `BUYERPAYINTRCNTNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '买方付息合作协议编号',
  `INTPYMT_PSN_NM` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息人名称',
  `INTPYMT_PSN_ACCNO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息人账号',
  `AOACCNINF_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `AB_DISCOUNT_RECORD_ID_IDX` (`RECORD_ID`),
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='贴现流水对应一条贴现明细信息';

DROP TABLE IF EXISTS `ab_draft_exc`;

CREATE TABLE `ab_draft_exc` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `VOUCHER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据主表ID',
  `RECORD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '流水表ID',
  `PAYERACC` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '持票人账号',
  `BIF_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行接口代码',
  `ORIG_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据号',
  `MSGTYPE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '消息类型（支付信用01\\背面信息02\\背面信息03）',
  `OPER_DATE` datetime DEFAULT NULL COMMENT '操作日期',
  `STATUS` decimal(38,0) DEFAULT NULL COMMENT '状态',
  `RETURN_CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '返回代码',
  `RETURN_MSG` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '返回消息',
  `SIGN_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SBBLL_RNG_STRT_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间开始序号。旧票据默认0，新票据 12位长度，不足12位前面补0',
  `SBBLL_RNG_END_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间结束区间',
  `IS_NO_VALUE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否确认无此子票信息，1确认无信息，其他为有',
  `BILL_TYPE` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SIGN_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_AB_DRAFT_EXC_ORIG_SBBLL` (`ORIG_NO`,`MSGTYPE`,`STATUS`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='指令查询表（支付信用\\正面信息、背面信息）';

DROP TABLE IF EXISTS `ab_emit_bail_interest_info`;

CREATE TABLE `ab_emit_bail_interest_info` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据单位id',
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据单位名称',
  `BANK_ACC` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据账号',
  `BANK_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型id',
  `BANK_TYPE_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型名称',
  `CURRENT_MONTH` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '当前月份',
  `BILL_MONEY` decimal(20,2) DEFAULT NULL COMMENT '票面金额',
  `BAIL_MONEY` decimal(20,2) DEFAULT NULL COMMENT '保证金金额',
  `DUE_SETTLEMENT_AMOUNT` decimal(20,2) DEFAULT NULL COMMENT '到期解付金额',
  `ACTUAL_SETTLEMENT_AMOUNT` decimal(20,2) DEFAULT NULL COMMENT '实际结算金额',
  `INTEREST_MARGIN` decimal(20,2) DEFAULT NULL COMMENT '利息差额',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '单据状态 0-暂存,1-已确认',
  `PUSH_STATUS` decimal(10,0) DEFAULT NULL COMMENT '推送状态 0-未推送,1-待推送,2-已推送',
  `RECORD_SOURCE` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记录来源 0-自动生成 1-手动增加',
