DROP TABLE IF EXISTS `ab_pool_finaapply_book`;

CREATE TABLE `ab_pool_finaapply_book` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `APPLY_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '申请代码',
  `CUST_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户标识号',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位id',
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位名称',
  `BP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据池id',
  `FINANCE_AMT` decimal(15,2) DEFAULT NULL COMMENT '融资金额',
  `BILL_TYPE` decimal(6,0) DEFAULT NULL COMMENT '票据类型：10 银票、11 商票',
  `APPLY_DATE` datetime DEFAULT NULL COMMENT '申请日期',
  `ST_DATE` datetime DEFAULT NULL COMMENT '起始日期',
  `END_DATE` datetime DEFAULT NULL COMMENT '到期日期',
  `APPLY_STATUS` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '申请状态 YT:已提交至银行,TH:银行退回,SL:银行已受理,CZ:已出账,JQ:已结清,YF：已重新提交',
  `APPLY_STATUS_NAME` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '申请状态名称',
  `BIZ_CODE` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务品种代码',
  `BIZ_NAME` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务品种名称',
  `REMARK` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `CURRENCY` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '货币种类 01：人民币',
  `CURRNAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '货币种类名称',
  `BUSINESS_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型 CT:传统业务;MJ:贸金业务',
  `BUSINESS_NAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型名称',
  `TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '商票交易类型 03:(出票、承兑） 05:(出票、承兑、提示收票)',
  `SRVR_ID` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '商票网银跟踪号',
  `UPIMAGE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否上传影像 01:是;02：否',
  `IMAGE_NAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否上传影像名称',
  `UPSUCCESS` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否上传成功 CG：成功;SB：失败',
  `SUCCESSNAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否上传成功名称',
  `CONTRACT_CODE` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '协议(合同)代码',
  `CONTRACT_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '协议(合同)编号',
  `CONTRACT_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '协议(合同)名称',
  `FIRMARGIN_ACCTID` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '初始保证金账号',
  `FIRMARGIN_AMT` decimal(15,2) DEFAULT NULL COMMENT '初始保证金总额',
  `FIRMARGIN_PERCTGE` decimal(15,2) DEFAULT NULL COMMENT '初始保证金比例',
  `BACMARGIN_ACCTID` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '回款保证金账号',
  `ACCTID` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款账号',
  `FINPURPOSE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '融资用途',
  `APPLYDESC` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '申请说明',
  `RETURNREASON` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '退回原因',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新日期',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据池融资申请登记薄';

DROP TABLE IF EXISTS `ab_pool_finaapply_dtl`;

CREATE TABLE `ab_pool_finaapply_dtl` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `BOOK_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '登记薄ID',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位id',
  `APPLY_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '申请代码',
  `CUST_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户标识号',
  `ORIG_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据号码',
  `BILL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '票据金额',
  `BUS_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务种类 03:(出票、承兑）05:(出票、承兑、提示收票) 09：贴现',
  `BILL_STATUS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据状态',
  `PAYER` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人',
  `PAYERACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人账号',
  `PAYER_BANK_NAME` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人开户银行名称',
  `PAYERBANKNO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人开户银行行号',
  `PAYEE` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人全称',
  `PAYEEACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人账号',
  `PAYEE_BANK_NAME` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人开户银行名称',
  `PAYEEBANKNO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人开户银行行号',
  `ACCEPTOR` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人',
  `ACCEPTORACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人账号',
  `ACCEPTORBANKNO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人开户行行号',
  `ACCEPTOR_BANK_NAME` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人开户行名称',
  `START_DATE` datetime DEFAULT NULL COMMENT '出票日期',
  `END_DATE` datetime DEFAULT NULL COMMENT '到期日期',
