  `BIF_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '鎺ュ彛浠ｇ爜ID锛堝啑浣欙級',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `ab_voucherinfo`;

CREATE TABLE `ab_voucherinfo` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '票据主表id',
  `ORIG_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据号码',
  `BILL_TYPE` decimal(6,0) DEFAULT NULL COMMENT '票据类型：10 银票、11 商票',
  `BANENDRSMTMK` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '不得转让标记EM00可再转让EM01不得转让',
  `BOX_STATUS` decimal(6,0) DEFAULT NULL COMMENT '处理标记 10正在处理11处理完成',
  `BILL_STATUS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据状态',
  `BILL_FLAG` decimal(6,0) DEFAULT NULL COMMENT '流通介质：10 纸票、11 电票',
  `BILL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '票据金额',
  `START_DATE` datetime DEFAULT NULL COMMENT '出票日期',
  `END_DATE` datetime DEFAULT NULL COMMENT '到期日期',
  `PAYER` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人',
  `PAYERACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人账号',
  `PAYER_BANK_NAME` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人开户银行名称',
  `PAYERBANKNO` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人开户银行行号',
  `PAYEE` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人全称',
  `PAYEEACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人账号',
  `PAYEE_BANK_NAME` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人开户银行名称',
  `PAYEEBANKNO` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人开户银行行号',
  `ACCEPTOR` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人',
  `ACCEPTORACC` varchar(46) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人账号',
  `ACCEPTORBANKNO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACCEPTOR_BANK_NAME` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人开户行名称',
  `ACCEPTORBANKADDRESS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '承兑人开户行地址',
  `AR_XCLX` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '瑕疵类型 通过数据字典维护',
  `A_CONTRACT_NO` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑合同号',
  `A_INVCNB` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发票号',
  `ACCPTNCAGRMTNB` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑协议编号',
  `PAYER_CDT_RATGS` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '开票信用等级',
  `PAYER_CDT_RATG_AGCY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '开票评级机构',
  `PAYER_CDT_RATG_DUEDT` datetime DEFAULT NULL COMMENT '开票评级到期日',
  `SOURCE_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '来源类型 0应付票据，1应收票据',
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人名称',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人名称',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `CREDIT_RATING` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PAYEE_BANK_TYPE_ID` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收票人银行类型',
  `ACCEPTOR_ACC_BANK_TYPE_ID` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人账号银行类型',
  `BL_BSN_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据业务类型代码',
  `NEW_STM_ISSUOFPPR_IND` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '出票标志。0：老系统出票,   1：新系统出票。默认值为0，不能为空',
  `BLGRDBAGCRCL_PRMT_IND` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '是否允许分包。1 是  0 否，默认为否  新系统出票标志为"0"(老系统出 票) 时，只能填写"0"(不可分包流 转)',
  `SBBLL_RNG_STRT_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间开始序号。旧票据默认0，新票据 12位长度，不足12位前面补0',
  `SBBLL_RNG_END_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '子票区间结束序号。旧票据默认0，新票据 12位长度，不足12位前面补0',
  `BL_STD_AMT` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '标准金额。单位元. 旧票据无，新票据默认为0.01',
  `BL_RMTR_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出票人统一社会信用代码。旧票据可无，新票据需展示',
  `BL_ACPTR_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人统一社会信用代码。旧票据可无，新票据需展示',
  `BL_RCVPYMTPS_UNN_ID_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人统一社会信用代码。旧票据可无，新票据需展示',
  `BL_ACPTR_ID_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承兑人识别类型。DT01 票据账户DT02 银行账户  暂时固定为“银行账户”。旧票据可无',
  `BL_RCVPYMTPS_ID_TPCD` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人人识别类型。DT01 票据账户DT02 银行账户  暂时固定为“银行账户”。旧票据可无',
  `EBILL_BL_CRCL_INDC` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据流通标志',
  `OLD_DRAFT_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '拆分前的票据id',
  `AGREE_BILL_FLG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '是否协议出票',
  `COOPERATIVE_BANK_NO` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '合作银行号',
  `RISK_BILL_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `DISOUNT_INC_IF` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CASH_INC_IF` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `AVOID_CLAIM_DEBTS_IF` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PAYER_CHANNEL_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACCEPTOR_CHANNEL_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PAYEE_CHANNEL_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ORG_SBBLL_RNG_STRT_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ORG_SBBLL_RNG_END_SN` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ENDORSEMENT_COUNT` decimal(12,0) DEFAULT NULL,
  `risk_contract_number` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '风险合同编号',
  `cvm_limit_no` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'CVM额度编号',
  `accptncagrmt_branch` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银承合作协议分行',
  `accptncagrmt_branch_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银承合作协议分行行号',
  `CMB_BNKBILNEG_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '招行合作框架协议表id',
  `CMB_CRLCON_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '招行风险合同信息表id',
  `REPEAT_REC_SIGN` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CMB_BAIL_FLAG` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '特定银行保证金选择标识 0-否 1-招行 2-民生',
  `RMK` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_AB_VOUCHERINFO_ORIGNOSBBLNO` (`ORIG_NO`,`SBBLL_RNG_STRT_SN`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='票据票面的信息';

