  `CD_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '借贷标志',
  `AMT` decimal(19,2) DEFAULT NULL COMMENT '交易金额',
  `BAL` decimal(19,2) DEFAULT NULL COMMENT '余额',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别ID',
  `USES` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `POSTSCRIPT` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REMARK` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TRANS_TIME` datetime(6) DEFAULT NULL,
  `VOUCHER_NO` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '企业流水号',
  `BANK_SERIAL_NO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行流水号',
  `RETURN_TIME` datetime DEFAULT NULL COMMENT '返回时间',
  `RB_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '红蓝标志',
  `ACC_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务单号',
  `IMPORT_SIGN` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '导出标识',
  `IMPORT_DATE` datetime DEFAULT NULL COMMENT '导出时间',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `FBS_STATUS` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '资金计划挂接状态 0未确认 1已确认 2已删除',
  `PROJECT_REMARK` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '项目信息',
  `SETTL_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BLEND_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `REFUND_BLEND_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RMK` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BILL_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `MERGE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SPLIT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `STATUS` int DEFAULT NULL,
  `BUS_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CLAIM_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '票据认领中间表id',
  `BIS_DTL_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BIS_EBILL_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `AUTO_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `corp_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位ID',
  `corp_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位名称',
  `bank_type_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类型',
  `bank_type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类别名称',
  `CUR_NAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别名称',
  `PAYMENTBLENDING_DATE` datetime(6) DEFAULT NULL,
  `AUTO_SIGN_DATE` datetime(6) DEFAULT NULL,
  `mactibkn` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `mactacn` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `mactname` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `mactbank` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RETURN_MSG` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TALLY_DATE` datetime(6) DEFAULT NULL,
  `TRANSACTION_TYPE_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TRANSACTION_TYPE_NAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RECEIPT_BLEND_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `REFUND_BLEND_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '退款勾对人',
  `REFUND_BLEND_TIME` datetime DEFAULT NULL COMMENT '退款勾对时间',
  `DTL_SYNC_STATUS` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据发送状态 F失败 S成功',
  `BOOK_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记账凭证FC_ACCBOOK的ID',
  `BUS_GLOBAL_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '全局业务ID',
  `ESTATE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记账状态',
  `TALLY_VOUCHER_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '自动记账凭证号',
  `ORDER_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '流水号',
  `TALLY_FAIL_MSG` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '自动记账失败原因',
  `TALLY_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记账标识',
  `OPERATOR_CODE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记账人',
  `AGAIN_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `SOURCE_NUM` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '共享单号',
  `OP_TIME` datetime DEFAULT NULL COMMENT '流水推送时间',
  `BFS_REQUEST_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '资金推送批次',
  `GX_DTL_SYNC_STATUS` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '共享数据发送状态 F失败 S成功',
  `GX_OP_TIME` datetime DEFAULT NULL COMMENT '共享流水推送时间',
  `GX_SOURCE_NUM` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '共享共享单号',
  `POOL_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `POOL_BLEND_SIGN` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  `WRITE_OFF_STATUS` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '核销状态',
  `WRITE_OFF_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '核销类型',
  `WRITE_OFF_BAL` decimal(19,2) DEFAULT NULL COMMENT '核销收入余额',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIS_ACC_DTL` (`BANK_ACC`,`TRANS_TIME`),
  KEY `IDX_BIS_ACC_DTL_CD_SIGN` (`CD_SIGN`),
  KEY `IDX_BIS_ACC_DTL_BA_CI_TT` (`BANK_ACC`,`CUR_ID`,`TRANS_TIME`),
  KEY `IDX_BIS_ACC_DTL_ACC_NO` (`ACC_NO`),
  KEY `IDX_STATUS_BANKACC_TRANSTIME` (`STATUS`,`BANK_ACC`,`TRANS_TIME`),
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='银行账号明细表';

