  `CLOSING_BALANCE` decimal(19,2) DEFAULT NULL COMMENT '期末余额',
  `TOTAL_NUMBER` int DEFAULT NULL COMMENT '汇总交易笔数',
  `TOTAL_DEBIT_AMT` decimal(19,2) DEFAULT NULL COMMENT '汇总借方发生额',
  `TOTAL_CREDIT_AMT` decimal(19,2) DEFAULT NULL COMMENT '汇总贷方发生额',
