  `PDF_TO_IMG` longblob,
  `PRINTS` decimal(10,0) DEFAULT NULL,
  `CD_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BLEND_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `IS_FROM` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0',
  `STATUS` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SAVE_TYPE` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `FILE_PATH` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BIS_DTL_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BIS_EBILL_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT CURRENT_TIMESTAMP,
  `EBILL_FTP_ADDRESS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CRLOGACCNO` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CRLOGACCNAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `AUTO_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIS_BANK_RECEIPT_DTL` (`TRANS_AMT`,`PAY_ACC_NO`,`CHARAGE_DATE`) USING BTREE,
  KEY `IDX_BANK_RECEIPT_DATE` (`CHARAGE_DATE`) USING BTREE,
  KEY `IDX_BIS_BANK_RECEIPT_DTL_BIS_EBILL_NO` (`BIS_EBILL_NO`,`BLEND_SIGN`,`AUTO_SIGN`) USING BTREE,
  KEY `IDX_BIS_BANK_RECEIPT_DTL_BANK` (`BIF_CODE_ID`,`BLEND_SIGN`,`CD_SIGN`,`AUTO_SIGN`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='电子回单指令表';

