  `add_word` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VOUCHER_FROM` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指令来源 1-付款、2-下拨、3-请款、4-头寸调拨、5-上划、6-上缴、7-自动下拨、8-自动归集、9-柜台手工记账、10-代发工资',
