DROP TABLE IF EXISTS `bis_gather_cmd`;

CREATE TABLE `bis_gather_cmd` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `VOUCHER_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '指令编号',
  `BIF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口代码',
  `CBS_BILL_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调拨单ID',
  `CHILD_ACC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '子账号',
  `PARENT_ACC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '父账号',
  `GATHER_AMT` decimal(15,2) NOT NULL COMMENT '金额',
  `GATHER_POLICY_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调拨策略ID',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '币别',
  `RUN_TIME` datetime DEFAULT NULL COMMENT '执行日期',
  `IS_QUICK` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '加急标志 1-是 0-否',
  `DIF_BANK` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '跨行标识 0-同行 1-他行',
  `AREA_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '地域标识 0-同城 1-异地',
  `PURPOSE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用途',
  `ADD_WORD` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附言',
  `VOUCHER_FROM` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指令来源 1-付款、2-下拨、3-请款、4-头寸调拨、5-上划、6-上缴、7-自动下拨、8-自动归集、9-柜台手工记账、10-代发工资',
  `BUS_ORI_TYPE` decimal(2,0) DEFAULT NULL COMMENT '业务类型',
  `DTL_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行流水ID',
  `BANK_SERIAL_NO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行流水号',
  `CMD_STAT` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '交易状态',
  `TRANS_TIME` datetime DEFAULT NULL COMMENT '交易时间',
  `RETURN_TIME` datetime DEFAULT NULL COMMENT '返回时间',
  `FIRST_RETURN_MSG` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NEXT_RETURN_MSG` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CMD_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CBS_BILL_NO` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NOTICE_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RETURN_TRANS_MSG` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VERIFY_CODE` varchar(3000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RESEND_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BIS_DTL_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BIS_EBILL_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHILD_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHILD_ACC_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHILD_BANK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHILD_PROV` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHILD_CITY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PARENT_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PARENT_ACC_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PARENT_BANK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PARENT_PROV` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PARENT_CITY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIS_GATHER_CMD_CBI_VF_CS` (`CBS_BILL_ID`,`VOUCHER_FROM`,`CMD_STAT`) USING BTREE,
  KEY `IDX_BIS_GATHER_CMD01` (`VOUCHER_NO`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='收款指令表';

DROP TABLE IF EXISTS `bis_gather_cmd_send`;

CREATE TABLE `bis_gather_cmd_send` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `send_date` datetime DEFAULT NULL COMMENT '发送时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='收款指令发送表';

DROP TABLE IF EXISTS `bis_gather_policy`;

CREATE TABLE `bis_gather_policy` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'id',
  `GATHER_POLICY_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '调拨策略代码',
  `GATHER_POLICY_NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调拨策略名称',
  `DEF_DATE` datetime NOT NULL COMMENT '策略生效日期（yyyy/MM/dd）',
  `LAUNCH_TIME` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '策略生效时间',
  `GATHER_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调拨类型0-定时归集，1-实时归集，2-定时下拨',
  `FRQ_MODE` decimal(10,0) DEFAULT NULL COMMENT '调拨周期4-按日，8-按周，16-按月，32-按季，64-按年',
  `SERIAL_DAY` decimal(10,0) DEFAULT NULL COMMENT '调拨日 间隔时长以天为单位周策略：选择周一至周日月策略：选择1号到31号',
  `MAX_AMT` decimal(15,2) DEFAULT NULL COMMENT '金额上限',
  `MIN_AMT` decimal(15,2) DEFAULT NULL COMMENT '金额下限（最小执行额度）',
  `GATHER_MODE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '策略模式（归集/下拨方式）',
  `GATHER_AMT` decimal(15,2) DEFAULT NULL COMMENT '调拨金额（留底资金金额/取整单位/留底资金金额/固定上划金额/账户固定余额/下拨固定额度）',
  `DOWN_FIXED_AMT` decimal(15,2) DEFAULT NULL COMMENT '下拨固定额度（定时下拨，余额不足时固定额度下拨时，保存下拨固定额度）',
  `APP_NEXT_TIME` datetime DEFAULT NULL COMMENT '下一次下拔时间',
  `DIFFER_SCALE` decimal(6,4) DEFAULT NULL COMMENT '比例',
  `IS_QUICK` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '加急标志 1-是 0-否',
  `VALID_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '有效标志 1-有效 0-无效',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `AUTO_FILTER_HOLIDAYS` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PURPOSE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ADD_WORD` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `AUTO_FILTER_HOLIDAYS_RULE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '1',
  `FAIL_HANDLE_METHOD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `END_DATE` datetime DEFAULT NULL COMMENT '策略结束日期（yyyy/MM/dd）',
  `END_TIME` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '策略结束时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='调拨策略表';

DROP TABLE IF EXISTS `bis_gather_policy_account`;

CREATE TABLE `bis_gather_policy_account` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'id',
  `CORP_NAME` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位名称',
