) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='虚拟账号操作指令表';

DROP TABLE IF EXISTS `bp_bankinfo_register`;

CREATE TABLE `bp_bankinfo_register` (
  `BANKINTF_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '接口代码',
  `BANKINTF_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口银行',
  `BANKINTF_IP` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口IP地址',
  `BANKINFT_PORT` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口端口',
  `ALLOW_MAXTHREAD` int DEFAULT NULL COMMENT '允许最大线程数',
  `LQCREATE_FLAG` int DEFAULT NULL COMMENT '是否已生成队列',
  `RUN_FLAG` int DEFAULT NULL COMMENT '启停标志：0-停止，1-启动',
  `WHO_START` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '启停人',
  `START_TIME` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '启停时间',
  `BATCH_FLAG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BATCH_NUM` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BATCH_DTLNUM` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RUN_MODE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `HISBAL_BACKDAYS` int DEFAULT NULL,
  `HISDTL_BACKDAYS` int DEFAULT NULL,
  `CHECKINFO_BACKDAYS` int DEFAULT NULL,
  `CHARGE_FLAG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHARGE_BACKDAYS` int DEFAULT NULL,
  `BIF_CODE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BATCH_BALFLAG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BATCH_BALNUM` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BAL_INTERVAL_TIME` int DEFAULT '600' COMMENT '余额查询间隔时间',
  `BAL_CONTINUE_FLAG` int DEFAULT '1' COMMENT '余额查询继续发送请求标志：0-否，1-是',
  `DTL_INTERVAL_TIME` int DEFAULT '600' COMMENT '明细查询间隔时间',
  `DTL_CONTINUE_FLAG` int DEFAULT '1' COMMENT '明细查询继续发送请求标志：0-否，1-是',
  `BANK_BRANCH_FLAG` int DEFAULT NULL,
  `TRANS_CONTINUE_FLAG` int DEFAULT '1' COMMENT '交易结果查询继续发送请求标志：0-否，1-是',
  `TRANS_INTERVAL_TIME` int DEFAULT '600' COMMENT '交易结果查询间隔时间',
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`BANKINTF_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='平台银行接口注册与控制信息表';

