CREATE TABLE `bp_bankinfo_register_bill` (
  `BANKINTF_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '接口代码',
  `BANKINTF_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口银行',
