  `CONSUMER_NAME` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户端消费者名称',
  `SINGLE_THREAD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '线程标志 0-单线程 1-多线程',
  `INTERVAL_TIME` int DEFAULT '0' COMMENT '请求间隔时间',
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`CONSUMER_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
