DROP TABLE IF EXISTS `bp_client_consumer_bill`;

CREATE TABLE `bp_client_consumer_bill` (
  `CONSUMER_CODE` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '客户端消费者编号',
  `BIF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '银行接口编号',
  `CONSUMER_NUM` int DEFAULT NULL COMMENT '客户端消费者数量',
  `SINGLE_THREAD` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '线程标志 0-单线程 1-多线程',
  `INTERVAL_TIME` int DEFAULT '0' COMMENT '请求间隔时间',
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`CONSUMER_CODE`,`BIF_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `bp_dubious_trade`;

CREATE TABLE `bp_dubious_trade` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `business_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `check_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `foreign_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `bp_excute_bank`;

CREATE TABLE `bp_excute_bank` (
  `TRADE_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '交易编码 关联bp_trade_baseinfo',
  `BIF_CODE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '接口ID 关联bp_bankinfo_register',
  `BIF_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口编号 关联bp_bankinfo_register',
  `BANK_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`TRADE_CODE`,`BIF_CODE_ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='执行银行信息表';

DROP TABLE IF EXISTS `bp_excute_bank_bill`;

CREATE TABLE `bp_excute_bank_bill` (
  `TRADE_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '交易编码 关联bp_trade_baseinfo_bill',
  `BIF_CODE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '接口ID 关联bp_bankinfo_register_bill',
  `BIF_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口编号 关联bp_bankinfo_register_bill',
  `BANK_TYPE_ID` varchar(32) DEFAULT NULL,
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`TRADE_CODE`,`BIF_CODE_ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='执行银行信息表';

DROP TABLE IF EXISTS `bp_param`;

CREATE TABLE `bp_param` (
  `ID` decimal(15,0) NOT NULL COMMENT '主键ID',
  `CODE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '参数代码',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数名称',
  `DISPLAY_LABEL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '显示名称标题',
  `DISPLAY_LABEL_HINT` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '显示名称标题提示',
  `PARAM_VALUE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数值',
  `PARAM_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数类型（1:文本框，2:数字，3:金额，4: 日期，5: 下拉框，6:单选框，7:复选框）',
  `OPTION_VALUES` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数可选值（针对下拉框、单选及复选框，值如：1:是;0:否。其它可为空）',
  `SEQ_NO` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '显示顺序号',
  `IS_VALIDED` decimal(1,0) DEFAULT NULL COMMENT '是否启用（0:禁用，1:启用）',
  `REMARK` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `AK_CODE_BP_PARAM` (`CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='银行接口系统参数表';

DROP TABLE IF EXISTS `bp_param_bill`;

CREATE TABLE `bp_param_bill` (
  `ID` decimal(15,0) NOT NULL COMMENT '主键ID',
  `CODE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数代码',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数名称',
  `DISPLAY_LABEL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '显示名称标题',
  `DISPLAY_LABEL_HINT` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '显示名称标题提示',
  `PARAM_VALUE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数值',
  `PARAM_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数类型（1:文本框，2:数字，3:金额，4: 日期，5: 下拉框，6:单选框，7:复选框）',
  `OPTION_VALUES` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '参数可选值（针对下拉框、单选及复选框，值如：1:是;0:否。其它可为空）',
  `SEQ_NO` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '显示顺序号',
  `IS_VALIDED` decimal(1,0) DEFAULT '1' COMMENT '是否启用（0:禁用，1:启用）',
  `REMARK` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `AK_CODE_BP_PARAM_BILL` (`CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='银行接口系统参数表';

DROP TABLE IF EXISTS `bp_queue_baseinfo`;

CREATE TABLE `bp_queue_baseinfo` (
  `QUEUE_CODE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '队列编码',
  `QUEUE_NAME` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '队列名称',
  `QUEUE_TYPE` int DEFAULT NULL COMMENT '类别',
  `QUEUE_NOTE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`QUEUE_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='平台队列队列基础信息表';

DROP TABLE IF EXISTS `bp_queue_baseinfo_bill`;

CREATE TABLE `bp_queue_baseinfo_bill` (
  `QUEUE_CODE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '队列编码',
  `QUEUE_NAME` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '队列名称',
  `QUEUE_TYPE` int DEFAULT NULL COMMENT '类别',
  `QUEUE_NOTE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`QUEUE_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='平台队列队列基础信息表';

DROP TABLE IF EXISTS `bp_trade_baseinfo`;

CREATE TABLE `bp_trade_baseinfo` (
  `TRADE_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '交易编码',
  `TRADE_NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '交易名称',
  `MONITOR_LQ` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '监控队列',
  `DEFAULT_LQ` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '默认结果存放队列',
  `TRIGG_IMPLCLASS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '对应触发器实现类',
  `TRADEOF_BANKINTF` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BATCH_FLAG` int NOT NULL COMMENT '是否支持批量',
  `MUXTHREAD_FLAG` int NOT NULL COMMENT '是否支持多线程',
  `TIMERANGE_FLAG` int NOT NULL COMMENT '是否支持时间跨度',
  `EXCEPTION_TIMERANGE` int NOT NULL COMMENT '异常判定时间',
  `SHOW_ORDER` int NOT NULL COMMENT '显示顺序',
  `TRADE_TYPE` int NOT NULL COMMENT '交易类别说明',
  `INUSE_FLAG` int DEFAULT NULL COMMENT '启用停用标志',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`TRADE_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='平台交易基础信息表';

DROP TABLE IF EXISTS `bp_trade_baseinfo_bill`;

CREATE TABLE `bp_trade_baseinfo_bill` (
  `TRADE_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '交易编码',
  `TRADE_NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '交易名称',
  `MONITOR_LQ` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '监控队列',
  `DEFAULT_LQ` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '默认结果存放队列',
  `TRIGG_IMPLCLASS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '对应触发器实现类',
  `TRADEOF_BANKINTF` varchar(2000) DEFAULT NULL,
  `BATCH_FLAG` int NOT NULL COMMENT '是否支持批量',
  `MUXTHREAD_FLAG` int NOT NULL COMMENT '是否支持多线程',
  `TIMERANGE_FLAG` int NOT NULL COMMENT '是否支持时间跨度',
  `EXCEPTION_TIMERANGE` int NOT NULL COMMENT '异常判定时间',
  `SHOW_ORDER` int NOT NULL COMMENT '显示顺序',
  `TRADE_TYPE` int NOT NULL COMMENT '交易类别说明',
  `INUSE_FLAG` int DEFAULT NULL COMMENT '启用停用标志',
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`TRADE_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='平台交易基础信息表';

DROP TABLE IF EXISTS `bp_trans_cust_login`;

CREATE TABLE `bp_trans_cust_login` (
  `ID` decimal(15,0) NOT NULL,
  `CUST_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '用户代码',
  `TRANSFER_DEC_KEY` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '通讯对称密钥',
  `LOGIN_SESSION_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '上次登录会话id',
  `LOGIN_TIME` datetime DEFAULT NULL COMMENT '上次登录时间',
  `STATE` decimal(3,0) DEFAULT NULL COMMENT '登录状态（1-已登录;2-正在登出;3-已登出）',
  `BANK_CODES` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '银行代码（多个逗号分割）',
  `BANK_STATES` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '银行状态（与银行代码对应,值:2-银行运行中;4-银企接口连接银行失败;8-银行错误;32-任务调度已停止;33-任务调度的队列状态正常;34-任务调度的队列剩余容量过小;35任务调度的队列容量已满）',
  `REMARK` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '备注',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='银行接口平台交易用户登录表';

DROP TABLE IF EXISTS `bp_trans_cust_login_bill`;

CREATE TABLE `bp_trans_cust_login_bill` (
  `ID` decimal(15,0) NOT NULL COMMENT '主键ID',
  `CUST_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用户代码',
  `TRANSFER_DEC_KEY` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '通讯对称密钥',
  `LOGIN_SESSION_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '上次登录会话id',
  `LOGIN_TIME` datetime DEFAULT NULL COMMENT '上次登录时间',
  `STATE` decimal(3,0) DEFAULT NULL COMMENT '登录状态（1-已登录;2-正在登出;3-已登出）',
  `BANK_CODES` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行代码（多个逗号分割）',
  `BANK_STATES` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行状态',
  `REMARK` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='银行接口平台交易用户登录表';

DROP TABLE IF EXISTS `bpm_approval_node`;

