  `OP` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作人员',
  `OP_NAME` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作人员姓名',
  `MESSAGE_TYPE` decimal(6,0) NOT NULL,
