DROP TABLE IF EXISTS `bv_print_format_dtl`;

CREATE TABLE `bv_print_format_dtl` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `PRINT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '打印主信息ID',
  `CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '取值字段',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名称描述',
  `PRINT_COORD` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '打印坐标',
  `IS_PRINT` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否打印',
  `FONT_SIZE` decimal(6,0) DEFAULT NULL COMMENT '字体大小',
  `FONT_SPACE` decimal(6,0) DEFAULT NULL COMMENT '字体间距',
  `CHAR_SIZE_BR` decimal(6,0) DEFAULT NULL COMMENT '多少字换行',
