  `VAL_PRINT_FMT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '值打印格式：01日期年YYYY；02日期月MM;03日期天DD；04日期yyyy-MM-dd;05日期yyyyMMdd',
  `ORDERNUM` decimal(6,0) DEFAULT NULL COMMENT ' 排序字段',
