DROP TABLE IF EXISTS `cho_bank_finance`;

CREATE TABLE `cho_bank_finance` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `BILL_NO` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '业务单号',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位ID',
  `BUS_TYPE` decimal(4,0) NOT NULL COMMENT '业务类型\n10-活期转定期\n11-定期转活期\n12-活期转通知\n13-通知转活期\n14-通知预约\n15-取消通知',
  `PAYER_ACC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款账号ID',
  `PAYER_ACC` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款账号',
  `BALANCE` decimal(15,2) DEFAULT NULL COMMENT '付款账户余额',
  `PAYEE_ACC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账号ID',
  `PAYEE_ACC` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账号',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别',
  `PAY_MONEY` decimal(15,2) DEFAULT NULL COMMENT '金额',
  `DAY_LIMIT` decimal(4,0) DEFAULT NULL COMMENT '期限（活期转定期）：3个月、6个月、1年、2年、3年、5年',
  `DATE_UNIT` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '日期单位 Y-年、M-月、D-日',
  `BURSAR_BILL_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '会计凭证号',
  `INTEREST` decimal(15,2) DEFAULT NULL COMMENT '利息',
  `CERTIFICATE_WAY` decimal(2,0) DEFAULT NULL COMMENT '到期处理方式\n0-不处理 1-本金续存 2-本息续存',
  `WISH_PAYDAY` datetime DEFAULT NULL COMMENT '期望支付日期',
  `INTEREST_RATE` decimal(8,6) DEFAULT NULL COMMENT '利率',
  `PURPOSE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用途',
  `ADD_WORD` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附言',
  `PAY_DATE` datetime DEFAULT NULL COMMENT '取款日期',
  `NOTIFY_TIME` datetime DEFAULT NULL COMMENT '通知日期',
  `BL_INTEREST_RATE` decimal(8,6) DEFAULT NULL COMMENT '补录利率',
  `IS_BL` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否补录 0-否 1-是',
  `BANK_BILL_NO` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '补录单号',
  `BL_INTEREST` decimal(15,2) DEFAULT NULL COMMENT '补录利息',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `PAY_BILL_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `INTEREST_START_DATE` datetime DEFAULT NULL,
  `DEADLINE_DATE` datetime DEFAULT NULL,
  `COLLECTION_CONFIRM` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_ONLINE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '单位名称',
  `bank_Acc_Online` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '账号上线',
  `bank_Name` varchar(140) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '付款开户行名称',
  `acc_Name` varchar(140) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '付款账号名称',
  `CUR_NAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '币种名称',
  `USERNAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '创建人登录名称',
  `exc_Id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '指令ID',
  `voucher_Stat` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '交易状态',
  `TIME_BALANCE` decimal(15,2) DEFAULT NULL COMMENT '定期账号余额',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='银行理财表';

