  `TALLY_DATE` date DEFAULT NULL,
  `ORDER_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VOUCHER_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TALLY_SIGN` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TALLY_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `NET_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '网点ID',
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '单位名称',
  `PAYER_ACC_NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款账户名称',
  `ACC_INTEREST_RATE` decimal(8,6) DEFAULT NULL COMMENT '付款账号利率',
  `PAYEE_ACC_NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账户名称',
  `CAPITAL_ACC` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '本金存入结算中心账号',
  `CAPITAL_ACC_NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '本金存入账户名称',
  `INTEREST_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利息存入结算中心账号',
  `INTEREST_ACC_NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利息存入账户名称',
  `PERIOD_NAME` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贷款周期的名称',
  `CUR_NAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '币种名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='内部理财信息表';

DROP TABLE IF EXISTS `cho_message`;

CREATE TABLE `cho_message` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ENROL_DATE` datetime NOT NULL COMMENT '录入时间',
  `BILL_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单据号',
  `OP` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作人员',
  `OP_NAME` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作人员姓名',
  `MESSAGE_TYPE` decimal(6,0) NOT NULL,
  `MESSAGE` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BUS_TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='理财日志表';

DROP TABLE IF EXISTS `cho_product_netval`;

CREATE TABLE `cho_product_netval` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编号',
  `REQ_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '理财产品登记表id',
  `REDEEM_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '理财产品续期id',
  `NET_VAL_DATE` datetime DEFAULT NULL COMMENT '净值维护日期',
  `BUY_MONEY` decimal(15,2) DEFAULT NULL COMMENT '购买日期',
  `BUY_PORTION` decimal(19,6) DEFAULT NULL COMMENT '购买份额',
  `DAILY_NET_VAL` decimal(19,6) DEFAULT NULL COMMENT '日净值',
  `TEN_THOUSAND_INCOME` decimal(15,2) DEFAULT NULL COMMENT '每万份收益',
  `DAY_INCOME` decimal(15,2) DEFAULT NULL COMMENT '当日收益',
  `ACTUAL_INCOME` decimal(15,2) DEFAULT NULL COMMENT '实际收益',
  `BAL` decimal(15,2) DEFAULT NULL COMMENT '余额',
