  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='理财产品净值维护表';

DROP TABLE IF EXISTS `cho_product_redeem`;

CREATE TABLE `cho_product_redeem` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `BILL_NO` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务单号',
  `REQ_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '产品登记单号',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位ID',
  `REDEEM_MONEY` decimal(15,2) DEFAULT NULL COMMENT '赎回金额',
  `REDEEM_DATE` datetime DEFAULT NULL COMMENT '赎回日期',
  `TRANSFER_DATE` datetime DEFAULT NULL COMMENT '到账日期',
  `INCOME_MONEY` decimal(15,2) DEFAULT NULL COMMENT '收益金额',
  `INCOME_RATE` decimal(8,6) DEFAULT NULL COMMENT '实际收益率',
  `RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `SUB_FEE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '申购费',
  `REDEEM_CHARGE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '赎回费',
  `CHARGE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '其他手续费',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `COLLECTION_CONFIRM` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REDEEM_PORTION` decimal(19,6) DEFAULT NULL COMMENT '赎回份额',
  `REDEEM_DAILY_NET_VAL` decimal(19,6) DEFAULT NULL COMMENT '赎回日净值',
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '单位名称',
  `BANK_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PRODUCT_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_ACC` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_STORE` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '到期是否续存',
  `CERTIFICATE_WAY` decimal(2,0) DEFAULT NULL COMMENT '续存模式 1-本金续存 2-本息续存',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='理财产品赎回表';

DROP TABLE IF EXISTS `cho_product_redeem_detail`;

CREATE TABLE `cho_product_redeem_detail` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
