  `INCOME_RATE` decimal(16,8) DEFAULT NULL,
  `RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SUB_FEE_MONEY` decimal(15,2) DEFAULT NULL,
  `REDEEM_CHARGE_MONEY` decimal(15,2) DEFAULT NULL,
  `CHARGE_MONEY` decimal(15,2) DEFAULT NULL,
  `COLLECTION_CONFIRM` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
