) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='理财产品赎回明细表';

DROP TABLE IF EXISTS `cho_product_renewal`;

CREATE TABLE `cho_product_renewal` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编号',
  `REDEEM_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '理财产品续期id',
  `DEADLINE_DATE` datetime DEFAULT NULL COMMENT '到期时间',
  `REFER_INCOME_MONEY` decimal(15,2) DEFAULT NULL COMMENT '参考收益',
  `DAY_LIMIT` decimal(8,0) DEFAULT NULL COMMENT '期限',
  `STATUS` decimal(2,0) DEFAULT NULL COMMENT '状态',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='理财产品续期表';

DROP TABLE IF EXISTS `cho_product_req`;

CREATE TABLE `cho_product_req` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `BILL_NO` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '业务单号',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位ID',
  `BANK_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '银行类别',
  `PRODUCT_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '产品类型',
  `PRODUCT_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '产品代码',
  `BANK_INFO_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '购买银行ID',
  `BANK_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '购买银行',
  `BANK_ACC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '理财账号ID',
  `BANK_ACC` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '理财账号',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别',
  `BUY_MONEY` decimal(15,2) DEFAULT NULL COMMENT '金额',
  `INCOME_CLAUSE` decimal(4,0) DEFAULT NULL COMMENT '收益条款：360-360天;365-365天',
  `BUY_DATE` datetime DEFAULT NULL COMMENT '购买日期',
  `DAY_LIMIT` decimal(8,0) DEFAULT NULL COMMENT '期限：期限=到期日期-起息日期,单位：天',
  `INTEREST_START_DATE` datetime DEFAULT NULL COMMENT '起息日期',
  `DEADLINE_DATE` datetime DEFAULT NULL COMMENT '到期日期',
  `CASH_DATE` datetime DEFAULT NULL COMMENT '兑付日期',
  `REFER_INCOME_RATE` decimal(8,6) DEFAULT NULL COMMENT '参考收益率',
  `SUB_FEE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '申购费',
  `REFER_INCOME_MONEY` decimal(15,2) DEFAULT NULL COMMENT '参考收益=购买金额*参考收益率*期限;360（除以360还是365以收益条款为准）',
  `CHARGE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '其他手续费',
  `IS_MOVE_UP` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是是否可提前赎回 0-否 1-是',
  `MOVE_UP_RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '提前赎回条约',
  `RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件ID',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `REDEEM_STATUS` decimal(10,0) DEFAULT NULL COMMENT '最近一条赎回记录的状态',
  `NOTICE_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '理财产品是否已经到期通知 1已通知  0未通知',
  `IS_GUARANTEED` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CAPITAL_SOURCE` int DEFAULT NULL,
  `BIZ_STATUS` decimal(4,0) DEFAULT NULL COMMENT '业务状态',
  `PAY_WAY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息方式',
  `CONTRACT_NO` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '合同号',
  `INCOME_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收益类型',
  `IS_STORE` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '到期是否续存',
  `START_CONTRACT_RATE` decimal(8,6) DEFAULT NULL COMMENT '起始合同利率',
  `END_CONTRACT_RATE` decimal(8,6) DEFAULT NULL COMMENT '结束合同利率',
  `DAILY_NET_VAL` decimal(19,6) DEFAULT NULL COMMENT '日净值',
  `PORTION` decimal(19,6) DEFAULT NULL COMMENT '份额',
  `IS_MAINTAIN_VAL` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '1' COMMENT '是否维护日净值',
  `END_REFER_INCOME_RATE` decimal(8,6) DEFAULT '1.000000' COMMENT '结束参考收益率',
  `END_REFER_INCOME_MONEY` decimal(15,2) DEFAULT NULL COMMENT '结束参考收益',
  `IS_BUY_APPLY` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0' COMMENT '是否为购买申请',
  `BUY_APPLY_STATUS` decimal(4,0) DEFAULT NULL COMMENT '购买申请状态',
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '单位名称',
  `BANK_TYPE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '银行类别名称',
  `CUR_NAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '' COMMENT '币种名称',
  `CERTIFICATE_WAY` decimal(2,0) DEFAULT NULL COMMENT '续存模式 1-本金续存 2-本息续存',
  `FINAN_ORG` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '购买机构 001银行 002券商',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='理财产品登记表';

