  `REDEEMED_MONEY` decimal(15,2) DEFAULT NULL COMMENT '已赎回金额',
  `INCOME_MONEY` decimal(15,2) DEFAULT NULL COMMENT '收益金额',
  `WAIT_REDEEM_MONEY` decimal(15,2) DEFAULT NULL COMMENT '待赎回金额',
  `AVERAGE_INCOME_RATE` decimal(10,8) DEFAULT NULL COMMENT '平均收益率',
  `REDEEMED_PORTION` decimal(19,6) DEFAULT NULL COMMENT '已赎回份额',
  `WAIT_REDEEM_PORTION` decimal(19,6) DEFAULT NULL COMMENT '待赎回份额',
  `REDEEM_CHARGE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '赎回费',
  `REDEEMED_PRINCIPAL` decimal(15,2) DEFAULT NULL COMMENT '已赎回本金',
  `HOLD_MONEY` decimal(15,2) DEFAULT NULL COMMENT '持有本金',
  `HOLD_INCOME_RATE` decimal(10,8) DEFAULT NULL COMMENT '持有收益率',
  `ANNUALIZED_INCOME_RATE` decimal(10,8) DEFAULT NULL COMMENT '年化收益率',
  `ANNUALIZED_INCOME` decimal(15,2) DEFAULT NULL COMMENT '年化收益',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='理财产品登记表历史报表';

DROP TABLE IF EXISTS `cho_product_type`;

CREATE TABLE `cho_product_type` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
