  `IS_LEAP_YEAR` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否闰年',
  `LEAP_IS_INTEREST` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '闰年是否计息',
  `INTEREST_DAYS` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计息实际天数',
  `FIX_PRICE_BASE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '定价基准',
  `RATE_DEADLINE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '利率期限',
  `BASE_RATE` decimal(8,6) NOT NULL COMMENT '基准利率',
  `BASIC_POINT` decimal(8,6) NOT NULL COMMENT '比例%/ BP点数',
  `FACE_VALUE_RATE` decimal(8,6) NOT NULL COMMENT '票面利率',
  `PAY_DATE` date NOT NULL COMMENT '付息日',
  `PAY_FREQUENCY` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '付息频率',
  `ASSIGN_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利息分配方式',
  `SPREAD_ISSUE` decimal(8,6) DEFAULT NULL COMMENT '发行时利差',
  `UPPER_LIMIT_RATE` decimal(8,6) DEFAULT NULL COMMENT '利率上限',
  `LOWEST_RATE` decimal(8,6) DEFAULT NULL COMMENT '保底利率',
  `RATE_EFFECT_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '基准利率生效方式',
  `EFFECT_PERIOD` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '生效时期',
  `EFFECT_CONDITION` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '生效条件',
  `INTEREST_RMK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利率信息说明',
  `IS_HOOK_BAIL` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂接保证金',
  `BAIL_CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金币种',
  `BAIL_BANK_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金账户',
  `BAIL_MONEY_RATE` decimal(8,6) DEFAULT NULL COMMENT '保证金比例',
  `ORI_BAIL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '保证金原币金额',
  `BAIL_MONEY_CONTRACT` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金合同',
  `BOND_RATE` decimal(8,6) DEFAULT NULL COMMENT '保证金利率',
  `RMB_BAIL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '保证金人民币金额',
  `IS_HOOK_GUARANTEE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂接担保',
  `GUARANTEE_RMK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保备注',
  `GUARANTEE_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保方式',
  `GUARANTEE_CONTRACT` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保合同',
  `GUARANTEE_MAN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保人',
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件id',
  `IS_HOOK_PLEDGE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂接抵质押物',
  `IS_DELETE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0' COMMENT '是否删除',
  `BIZ_STATUS` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务状态',
  `STATUS` int NOT NULL COMMENT '状态',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `UPDATE_DATE` date DEFAULT NULL COMMENT '修改时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='债劵发行信息表';

DROP TABLE IF EXISTS `cms_bond_pay`;

CREATE TABLE `cms_bond_pay` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编号',
  `ONLINE_PAYMENT_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账号',
  `ONLINE_ACC_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账户名称',
  `ONLINE_BANK_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人开户行行号',
  `ONLINE_BANK_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账户开户行名称',
  `REGISTER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '债券注册表id',
  `ISSUE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '债券发行表id',
  `STATUS` int DEFAULT NULL COMMENT '状态',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '所属单位',
  `PAY_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '支付订单号',
  `PAY_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '支付方式',
  `RMK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `PURPOSE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用途',
  `PAY_DATE` date DEFAULT NULL COMMENT '支付日期',
  `REPAY_MONEY` decimal(15,2) DEFAULT NULL COMMENT '还款本金',
  `INTEREST` decimal(15,2) DEFAULT NULL COMMENT '利息',
  `ONLINE_SIGN` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '线下线上还款标识',
  `ONLINE_STATUS` int DEFAULT NULL COMMENT '在线还款状态',
  `REPAY_TOTAL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '还款总金额',
  `IS_PAY_INTEREST` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否付息',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` date DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `UPDATE_DATE` date DEFAULT NULL COMMENT '修改日期',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='债劵还款支付表';

DROP TABLE IF EXISTS `cms_bond_register_info`;

CREATE TABLE `cms_bond_register_info` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编号',
  `TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '债劵类型表id',
