  `ISSUE_RMB_TOTAL` decimal(15,2) NOT NULL COMMENT '计划发行人民币总额',
  `BOND_CREDIT_RATE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '债劵信用评级',
  `DEBTOR_CREDIT_RATE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发行人信用评级',
  `CONVERT_START_DATE` date DEFAULT NULL COMMENT '可转换开始日',
  `CONVERT_END_DATE` date DEFAULT NULL COMMENT '可转换结束日',
  `CONVERT_RATE` decimal(8,6) DEFAULT NULL COMMENT '转换比例',
  `PURPOSE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '融资用途',
  `RMK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '债劵备注',
  `IS_TERRITORY` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '境内/境外',
  `STATUS` int NOT NULL COMMENT '状态',
  `IS_DELETE` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0' COMMENT '是否删除',
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件id',
  `CREATE_DATE` date DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `UPDATE_DATE` date DEFAULT NULL COMMENT '修改时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `CUR_NAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='债劵注册信息表';

DROP TABLE IF EXISTS `cms_bond_repay_plan`;

CREATE TABLE `cms_bond_repay_plan` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编号',
  `REGISTER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '债劵注册表id',
