  `SWAP_AMOUNT` decimal(13,0) NOT NULL COMMENT '换股数量',
  `TOTAL_SWAP_AMOUNT` decimal(13,0) NOT NULL COMMENT '累计换股数量',
  `TOTAL_SWAP_MONEY` decimal(15,2) NOT NULL COMMENT '累计换股金额',
  `STATUS` int NOT NULL COMMENT '交债状态',
  `CREATE_DATE` date DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `UPDATE_DATE` date DEFAULT NULL COMMENT '修改时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='可交债信息表';

DROP TABLE IF EXISTS `cms_bond_transfer`;

CREATE TABLE `cms_bond_transfer` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编号',
  `ISSUE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '债劵发行表id',
