  `FINANCING_DATE` date DEFAULT NULL COMMENT '融资日期',
  `DELIVERY_DATE` date DEFAULT NULL COMMENT '交割日期',
  `FINANCING_USE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '融资用途',
  `RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `UPLOAD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件ID',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
