  `REPAY_CYCLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利率期限',
  `POINTS_PROPORTION_TEXT` decimal(6,2) DEFAULT NULL COMMENT '点数或者比例值',
  `POINTS_PROPORTION_SELECT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '点数或者比例',
  `QUO_DATE` date DEFAULT NULL COMMENT '报价日期',
  `RATE` decimal(8,6) DEFAULT NULL COMMENT '利率',
  `RATE_BASE` decimal(10,0) DEFAULT NULL COMMENT '年度利率天数',
  `INTEREST_WAY` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计息方式',
  `RENT_CAL_WAY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租金计算方式',
  `INTEREST_FRE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息频率',
  `PAYMONEY_FRE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '本金支付频率',
  `PAYMENT_FRE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '费用支付频率',
  `BEGIN_PAYMONEY_DATE` date DEFAULT NULL COMMENT '租金起始支付日',
  `INS` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '说明',
  `IS_HOOK_BOND` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂保证金',
  `BOND_BANKACC` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金账户',
  `BOND_CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金币种',
  `EXPENDED_COUNT` decimal(10,0) DEFAULT NULL COMMENT '展期次数',
  `CONTINUE_COUNT` decimal(10,0) DEFAULT NULL COMMENT '续租次数',
  `BAILMONEY_RATE` decimal(8,6) DEFAULT NULL COMMENT '保证金比例',
  `ORI_BAILMONEY` decimal(15,2) DEFAULT NULL COMMENT '保证金原币金额',
  `RMB_BAILMONEY` decimal(15,2) DEFAULT NULL COMMENT '保证金人名币金额',
  `BOND_RATE` decimal(8,6) DEFAULT NULL COMMENT '保证金利率',
  `BAILMONEY_CONTRACT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金合同',
  `IS_HANG_GUARANTEE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂担保',
  `GUA_CONTRACT` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保合同编号',
  `GUA_MAN` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保人',
  `GUA_WAY` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保方式',
  `GUA_RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保备注',
  `IS_RELATE_PLEDGE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂抵质押物',
  `UPLOAD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件ID',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '承租人名称',
  `ORI_CUR_NAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='租赁变更表';

DROP TABLE IF EXISTS `cms_loan_deferred`;

CREATE TABLE `cms_loan_deferred` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '贷款展期流水号',
  `BILL_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '展期单号',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位代码',
  `LI_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '贷款发放单号',
  `CONTRACT_CODE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '展期合同号',
  `MATURE_DATE` datetime NOT NULL COMMENT '贷款到期日',
  `DEFERRED_LIMT` decimal(10,0) NOT NULL COMMENT '展期期限',
  `TERN_UNIT` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '期限单位',
  `DEFERRED_REPAY_DATE` datetime NOT NULL COMMENT '展期到期日',
  `LOAN_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '贷款账号',
  `RMK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `STATUS` decimal(10,0) NOT NULL COMMENT '状态',
  `DEFERRED_RATE` decimal(8,6) NOT NULL COMMENT '展期利率',
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件ID',
  `BIZ_STATUS` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务状态',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='贷款展期申请表';

DROP TABLE IF EXISTS `cms_loan_info`;

CREATE TABLE `cms_loan_info` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `NET_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '结算中心代码',
