  `BILL_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '贷款流水号',
  `CONTRACT_CODE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '借款合同号',
  `LOAN_MONEY` decimal(15,2) NOT NULL COMMENT '贷款金额',
  `LOAN_TERM` decimal(10,0) NOT NULL COMMENT '贷款期限',
