  `SURETY_MONEY` decimal(15,2) DEFAULT NULL COMMENT '担保品价值',
  `PROVIDE_LOAN_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '放款账号',
  `LOAN_RATE` decimal(8,6) DEFAULT NULL COMMENT '放款利率',
  `OVERDUE_RATE` decimal(8,6) DEFAULT NULL COMMENT '逾期利率',
  `DEFERRED_RATE` decimal(8,6) DEFAULT NULL COMMENT '展期利率',
  `REPAIR_OP` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '补录员',
  `STATUS` decimal(10,0) NOT NULL COMMENT '状态',
