  `SEND_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '贷款发放单号',
  `REPAY_MONEY` decimal(15,2) NOT NULL COMMENT '还款金额',
  `REPAY_DATE` datetime NOT NULL COMMENT '还款日期',
