  `POINTS_PROPORTION_SELECT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '点数或者比例',
  `RATE_ENTRIES_EFFECT_DATE` datetime DEFAULT NULL COMMENT '利率调整生效日期',
  `INTEREST_WAY` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计息方式',
  `REFERENCE_RATE_TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '基准利率类型',
  `REPAY_CYCLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贷款周期',
  `RATETIMEOFTAKEEFFECT` datetime DEFAULT NULL COMMENT '利率复核生效日期',
  `PAY_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '支付方式',
  `SEND_TIME` decimal(10,0) DEFAULT NULL COMMENT '发放次数',
  `BORROW_CORP_ID` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '借款单位',
  `REPAY_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CLB_AGREEMENT_RATE` decimal(15,6) DEFAULT NULL COMMENT '协定费率',
  `CLB_FIXED_RATE` decimal(9,6) DEFAULT NULL COMMENT '固定费率',
