  `POINTS_PROPORTION_SELECT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '点数或者比例',
  `RATE_ENTRIES_EFFECT_DATE` datetime DEFAULT NULL COMMENT '利率调整生效日期',
