DROP TABLE IF EXISTS `cms_provide_history`;

CREATE TABLE `cms_provide_history` (
  `ID` varchar(32) DEFAULT NULL COMMENT 'id',
  `REPORT_DATE` date DEFAULT NULL COMMENT '报表日期',
  `BANK_NAME` varchar(200) DEFAULT NULL COMMENT '借款银行',
  `CORP_ID` varchar(32) DEFAULT NULL COMMENT '申请单位',
  `PL_CLASS` varchar(4) DEFAULT NULL COMMENT '借款种类',
  `INFO_BILL_CODE` varchar(32) DEFAULT NULL COMMENT '借款单号',
  `SEND_BILL_CODE` varchar(32) DEFAULT NULL COMMENT '发放单号',
  `CONTRACT_CODE` varchar(50) DEFAULT NULL COMMENT '发放编号',
  `CREATE_DATE` date DEFAULT NULL COMMENT '创建日期',
  `CUR_ID` varchar(32) DEFAULT NULL COMMENT '借款币种',
  `PL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '借款金额',
  `SEND_MONEY` decimal(15,2) DEFAULT NULL COMMENT '发放金额',
  `SUM_REPAY_MONEY` decimal(15,2) DEFAULT NULL COMMENT '已还款本金',
