  `RMK` varchar(200) DEFAULT NULL COMMENT '备注',
  `CREATE_NAME` varchar(50) DEFAULT NULL COMMENT '创建人',
  `BIZ_STATUS` varchar(3) DEFAULT NULL COMMENT '状态',
  `CON_ID` varchar(32) DEFAULT NULL COMMENT '合同id',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='银行借款历史查询表';

