  `BILL_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型',
  `NET_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '网点',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别',
  `INTEREST_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计息类型',
  `REPAY_DATE` datetime DEFAULT NULL COMMENT '还款日期',
  `INTEREST_START_DATE` datetime DEFAULT NULL COMMENT '起息日期',
  `BLN_INST_DATE` datetime DEFAULT NULL COMMENT '结束日期',
  `DAYS` decimal(6,0) DEFAULT NULL COMMENT '计息天数',
  `CUMULATION` decimal(16,2) DEFAULT NULL COMMENT '积数',
  `RATE` decimal(8,6) DEFAULT NULL COMMENT '基准利率',
  `FLOAT_POINT` decimal(10,2) DEFAULT NULL COMMENT '浮动比例点数',
  `INTEREST_RATE` decimal(8,6) DEFAULT NULL COMMENT '计息利率',
  `RATE_FAX` decimal(8,6) DEFAULT NULL COMMENT '税率',
  `LOAN_MONEY` decimal(16,2) DEFAULT NULL COMMENT '本金',
  `REPAY_MONEY` decimal(16,2) DEFAULT NULL COMMENT '归还本金',
  `LEFT_MONEY` decimal(16,2) DEFAULT NULL COMMENT '剩余本金',
  `INTEREST` decimal(16,2) DEFAULT NULL COMMENT '归还本金利息',
  `PAY_INTEREST` decimal(16,2) DEFAULT NULL COMMENT '支付利息',
  `TOTAL_INTEREST` decimal(16,2) DEFAULT NULL COMMENT '全部利息',
  `UN_PAY_INTEREST` decimal(16,2) DEFAULT NULL COMMENT '未结利息',
  `INTEREST_FAX` decimal(16,2) DEFAULT NULL COMMENT '利息税率',
  `REAL_INTEREST` decimal(16,2) DEFAULT NULL COMMENT '实际付息',
  `INTEREST_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计息标识',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '还款状态',
  `RMK` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `REPAYMENT_SCHEDULE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '生成利息预计的还款计划ID',
  `SIGN_REPAY_DATE` datetime DEFAULT NULL COMMENT '还款日期标识_标识分段属于这个时间的还款',
  `REPAY_SIGN` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='借款利息预计明细';

