  `STATUS` decimal(6,0) DEFAULT NULL COMMENT '状态',
  `PL_PURPOSE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '借款用途',
  `RMK` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '备注',
  `IS_HANG_CREDIT` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂授信',
  `RATMODEL` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信模式',
  `RATION_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '额度编号',
  `ITEM_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '占用授信代码',
