  `IS_RMB_RAT` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否折合成本位币',
  `USERS` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '使用人',
  `CREDIT_CONTRACT_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '信贷合同号',
  `INSIDE_CONTRACT_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '内部合同号',
  `PROJECT_NAME` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '项目名称',
  `CPL_INTEREST_PAYMENT` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息方式',
  `INTERBUSEXPENSES` decimal(15,2) DEFAULT NULL COMMENT '中间业务费',
  `LOAN_SEND_OUT_TYPE` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发放方式',
  `FLOAT_WAY` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '浮动方式',
  `POINTS_PROPORTION_TEXT` decimal(6,2) DEFAULT NULL COMMENT '点数或浮动比例',
  `POINTS_PROPORTION_SELECT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '点数或者比例',
  `RATE_ENTRIES_EFFECT_DATE` datetime DEFAULT NULL COMMENT '利率调整生效日期',
  `INTEREST_WAY` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计息方式',
  `REFERENCE_RATE_TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '基准利率类型',
  `REPAY_CYCLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贷款周期',
  `RATETIMEOFTAKEEFFECT` datetime DEFAULT NULL COMMENT '利率复核生效日期',
  `ANTIC_INTEREST` decimal(15,2) DEFAULT NULL COMMENT '预计利息',
  `CONSULTANT_FEE_RATE` decimal(8,6) DEFAULT NULL COMMENT '顾问费利率',
  `CONSULTANT_FEE` decimal(15,2) DEFAULT NULL COMMENT '顾问费',
  `THIRD_PARTY_PROFIT_RATE` decimal(8,6) DEFAULT NULL COMMENT '第三方收益利率',
  `THIRD_PARTY_PROFIT` decimal(15,2) DEFAULT NULL COMMENT '第三方收益',
  `OTHER_FEE_RATE` decimal(8,6) DEFAULT NULL COMMENT '其他利率',
  `OTHER_FEE` decimal(15,2) DEFAULT NULL COMMENT '其他费用',
  `BOLISH_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '作废单号',
  `RATE_BASE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利息测算基数',
  `CONSULTANT_CB` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否勾选顾问费复选框',
  `THIRD_PARTY_CB` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否勾选第三方收益复选框',
  `OTHER_FEE_CB` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否勾其他利率复选框',
  `COMPOSITE_FEE_RATE` decimal(9,6) DEFAULT NULL COMMENT '综合成本年化利率',
  `COMPOSITE_FEE` decimal(15,2) DEFAULT NULL COMMENT '综合成本',
  `BAILMONEY_CONTRACT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REFUSE_WHY` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '打回原因',
  `ACROSS_SEND` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '跳过借款发放功能',
  `FLOAT_WAY_NEXT` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '浮动二级方式',
  `UPLOAD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BIZ_STATUS` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务状态',
  `FISCAL_QUARTER` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计息财务季度',
  `EXPIRY_DATE` decimal(6,0) DEFAULT NULL COMMENT '结息日',
  `ACCRUED_DAILY_DATE` decimal(6,0) DEFAULT NULL COMMENT '预提日',
  `BENCHMARK_RATE` decimal(8,6) DEFAULT NULL COMMENT '基准利率',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_HOOK_BOND` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `BOND_CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BOND_BANK_ACC` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_OPEN_RAT` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BILL_NAME` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_HANG_GUARANTEE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `GUARANTEE_RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BOND_RATE` decimal(8,6) DEFAULT NULL,
  `CON_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CON_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_RELATE_PLEDGE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `DEFERRED_POINTS` decimal(6,2) DEFAULT NULL,
  `OVERDUE_PROPORTION` decimal(6,2) DEFAULT NULL,
  `RATE_QUOTED_PRICE_DATE` datetime DEFAULT NULL,
  `IS_AUTO_PAY` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_OVER_REPAIR` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACCRUAL_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类别名称',
  `BANK_TYPE_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类别名称',
  `CORP_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位名称',
  `CORP_CODE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位编号',
  `BANK_CODE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行编号',
  `CUR_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别名称',
  `REPAY_CYCLE_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贷款期限名称',
  `ONLINE_PAYMENT_ACC` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ONLINE_PAYMENT_ACC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ONLINE_ACC_NAME` varchar(140) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ONLINE_BANK_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  `IS_DOMESTIC_BANK` VARCHAR(1) DEFAULT '1' COMMENT '是否境内银行 1-境内，0-境外',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='借款信息表';

DROP TABLE IF EXISTS `cms_provide_loan_rate`;

CREATE TABLE `cms_provide_loan_rate` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
