  `DEFERRED_RATE` decimal(8,6) DEFAULT NULL COMMENT '展期利率',
  `OVERDUE_RATE` decimal(8,6) DEFAULT NULL COMMENT '逾期利率',
  `STATUS` decimal(6,0) DEFAULT NULL COMMENT '状态',
