  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ONLINE_SIGN` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '线下线上还款标识',
  `ONLINE_REALITY_INTEREST` decimal(15,2) DEFAULT NULL COMMENT '实付利息',
  `ONLINE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '金额',
  `ONLINE_PAYMENT_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款帐号',
  `ONLINE_PURPOSE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用途',
  `ONLINE_ACC_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账户名称',
  `ONLINE_BANK_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账户开户行名称',
  `ONLINE_PAYMENT_ACC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款帐号ID',
  `ONLINE_OTHER_ACC_CHARGE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '线上还款其他应付款帐号',
  `ONLINE_STATUS` decimal(10,0) DEFAULT NULL COMMENT '在线还款状态',
  `REFUSE_WHY` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '打回原因',
  `TALLY_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TALLY_SIGN` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
