  `REPAY_CYCLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贷款周期',
  `RATETIMEOFTAKEEFFECT` datetime DEFAULT NULL COMMENT '利率复核生效日期',
  `ANTIC_INTEREST` decimal(15,2) DEFAULT NULL COMMENT '预计利息',
