  `ACCRUED_DAILY_DATE` decimal(6,0) DEFAULT NULL COMMENT '预提日',
  `FISCAL_QUARTER` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计息财务季度',
  `FLOAT_WAY_NEXT` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '浮动二级方式',
  `BENCHMARK_RATE` decimal(8,6) DEFAULT NULL COMMENT '基准利率',
