  `BLNCTR_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行活期账户',
  `DEFERRED_DATE` datetime DEFAULT NULL COMMENT '展期到期日期',
