CREATE TABLE `cms_repayment_schedule` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键ID',
  `CMS_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贷款类型',
  `BILL_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务单据号',
  `STATUS` decimal(5,0) DEFAULT NULL COMMENT '状态',
  `REPAY_BEGIN_DATE` datetime DEFAULT NULL COMMENT '还款开始日',
  `REPAY_CYCEL` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '还款周期',
  `LOAN_RATE` decimal(8,6) DEFAULT NULL COMMENT '利率',
  `LOAN_DATE` datetime DEFAULT NULL COMMENT '开始日期',
  `REPAY_DATE` datetime DEFAULT NULL COMMENT '还款日期',
  `REPAY_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '还款方式',
  `LOAN_MONEY` decimal(20,2) DEFAULT NULL COMMENT '金额',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='还款计划关联表';

DROP TABLE IF EXISTS `cms_repayment_scheduledetailed`;

CREATE TABLE `cms_repayment_scheduledetailed` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `BILL_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务单据号',
  `REPAY_CYCEL` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '还款周期 0:月 1:季度 2:半年度 3:一次性',
  `PREDICE_REPAY_DATE` datetime DEFAULT NULL COMMENT '预计还款日',
  `REPAYMENT_MONEY` decimal(20,2) DEFAULT NULL COMMENT '还款金额',
  `REPAYMENT_IST` decimal(20,2) DEFAULT NULL COMMENT '还款利息',
  `CURRENT_REPAY_MONEY` decimal(20,2) DEFAULT NULL COMMENT '本期还款金额',
  `REALITY_REPAY_DATE` datetime DEFAULT NULL COMMENT '实际还款日',
  `REALITY_REPAY_MONEY` decimal(20,2) DEFAULT NULL COMMENT '实际还款本金',
  `SURPLUS_MONEY` decimal(20,2) DEFAULT NULL COMMENT '剩余本金',
  `IS_REPAY` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '归还标识 0:否 1:是',
  `REMARK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `REPAYMENT_BEGIN_DATE` datetime DEFAULT NULL COMMENT '还款开始日',
  `VALID_SIGN` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '有效标志',
  `INTERNAL_SIGN` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '内部标志:A1 -内部贷款录入  A2 -- 内部贷款发放\nB1 -银行借款录入  B2 -- 银行借款发放',
  `RELATION_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '与主表关联id',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REPAY_SIGN` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='还款计划表';

