DROP TABLE IF EXISTS `cms_security_asset_type`;

CREATE TABLE `cms_security_asset_type` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'ID',
  `ASSET_TYPE_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '类型编码',
