DROP TABLE IF EXISTS `cms_security_info`;

CREATE TABLE `cms_security_info` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'ID',
  `SECURITY_TYPE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '资产证券化类型',
  `ISDOMESTIC` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '境内/境外',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原始权益人',
  `FINANCIER` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际融资人',
  `SECURITY_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证券代码',
  `SECURITY_SNAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证券简称',
  `SECURITY_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证券名称',
  `APPROVAL_NUMBER` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '批准文号',
  `TRUSTEE` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '受托机构',
  `ASSET_TYPE_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '基础资产类型',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证券原币币种',
  `MONEY` decimal(15,2) DEFAULT NULL COMMENT '计划发行原币总额',
  `RMB_MONEY` decimal(15,2) DEFAULT NULL COMMENT '计划发行人名币总额',
  `MEASURES` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '增信措施',
  `RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件id',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '修改时间',
  `CORP_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原始权益名称',
  `CUR_NAME` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `cms_security_issue`;

CREATE TABLE `cms_security_issue` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'id',
  `SECURITY_INFO_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '登记主信息表id',
  `SECURITY_ISSUE_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证券发行编号',
  `BATCH_NO` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '批次',
  `LEVEL_NAME` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '层级',
  `PRODUCT_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '产品名称',
  `ISSUE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '发行金额',
  `FACE_VALUE` decimal(15,2) DEFAULT NULL COMMENT '面值',
  `ISSUE_PRICE` decimal(15,2) DEFAULT NULL COMMENT '发行价格',
  `THIS_ISSUE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '本次发行金额',
  `ISSUE_DATE` date DEFAULT NULL COMMENT '发行日期',
  `ISSUE_RMB_MONEY` decimal(15,2) DEFAULT NULL COMMENT '发行折合人名币金额',
  `EXPECT_END_DATE` date DEFAULT NULL COMMENT '预期到期日',
  `LEGAL_END_DATE` date DEFAULT NULL COMMENT '法定到期日',
  `TIME_LIMIT` decimal(15,2) DEFAULT NULL COMMENT '期限',
  `REPAY_TYPE` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '还款方式',
  `ISSUE_WAY` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发行方式',
  `ISSUE_MARKET` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发行市场',
  `TABLE_PROPORTION` decimal(6,2) DEFAULT NULL COMMENT '出表比例',
  `CREDIT_RATING` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '信用评级',
  `CREDIT_RATING_INS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '信用评级机构',
  `UNDERWRITER` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '主承销商',
  `RE_TO_ACCOUNT_MONEY` decimal(15,2) DEFAULT NULL COMMENT '剩余应到账金额',
  `RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `COUPON_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '息票类型',
  `IS_FLOAT` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '浮动/固定',
  `PAR_RATE` decimal(8,6) DEFAULT NULL COMMENT '票面利率',
  `RATE_BASE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利息年度天数',
  `START_DATE` date DEFAULT NULL COMMENT '起息日',
  `INTEREST_WAY` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利息分配方式',
  `INTEREST_FRE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付息频率',
  `BEGIN_PAYINTEREST_DATE` date DEFAULT NULL COMMENT '首次付息日',
  `PAYMONEY_FRE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '本金支付频率',
  `BEGIN_PAYMONEY_DATE` date DEFAULT NULL COMMENT '首次本金支付日',
  `REFERENCE_RATE_TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '定价基准',
  `REPAY_CYCLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利率期限',
  `QUO_DATE` date DEFAULT NULL COMMENT '报价日期',
  `POINTS_PROPORTION_TEXT` decimal(8,6) DEFAULT NULL COMMENT '基准利差',
  `BASE_RATE` decimal(8,6) DEFAULT NULL COMMENT '首次基准利率',
  `UPPER_RATE` decimal(8,6) DEFAULT NULL COMMENT '利率上限',
  `LOWEST_RATE` decimal(8,6) DEFAULT NULL COMMENT '利率下限',
  `RATE_RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利率备注',
  `BASE_RATE_RULES` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '基准利率确定规则',
  `IS_HOOK_BOND` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂保证金',
  `BOND_BANKACC` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金账户',
  `BOND_CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金币种',
  `BAILMONEY_RATE` decimal(8,6) DEFAULT NULL COMMENT '保证金比例',
  `ORI_BAILMONEY` decimal(15,2) DEFAULT NULL COMMENT '保证金原币金额',
  `RMB_BAILMONEY` decimal(15,2) DEFAULT NULL COMMENT '保证金人名币金额',
  `BOND_RATE` decimal(8,6) DEFAULT NULL COMMENT '保证金利率',
  `BAILMONEY_CONTRACT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '保证金合同',
  `IS_HANG_GUARANTEE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂担保',
  `GUA_CONTRACT` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保合同编号',
  `GUA_MAN` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保人',
  `GUA_WAY` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保方式',
  `GUA_RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保备注',
  `IS_RELATE_PLEDGE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否挂抵质押物',
  `UPLOAD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件ID',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `BIZ_STATUS` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务状态',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  KEY `IDX_TENANT_ID` (`TENANT_ID`),
  unique key `UDX_SECURITY_ISSUE_CODE` (`SECURITY_ISSUE_CODE`,`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

