DROP TABLE IF EXISTS `cms_security_plan_detail`;

CREATE TABLE `cms_security_plan_detail` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'id',
  `SECURITY_ISSUE_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证券发行编号',
  `SECURITY_PLAN_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计划主表id',
