  `DATA_SOURCE_ORIGIN` varchar(1000) DEFAULT NULL COMMENT '数据来源的来源',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='数据来源表';

DROP TABLE IF EXISTS `cr_qua_method_for_scoring_ind`;

CREATE TABLE `cr_qua_method_for_scoring_ind` (
  `ID` varchar(32) NOT NULL COMMENT 'id',
  `SCORING_INDICATOR_ID` varchar(32) DEFAULT NULL COMMENT '外键.指标类别表（Indicator_Category）的主键',
  `SCORING_INDICATOR_CODE` varchar(4) DEFAULT NULL COMMENT '评分指标的代码',
  `SCORING_INDICATOR_NAME` varchar(100) DEFAULT NULL COMMENT '评分指标的名称',
  `SCORING_INDICATOR_DESCRIPTION` varchar(2000) DEFAULT NULL,
  `CATEGORY_ENCODING` varchar(4) DEFAULT NULL COMMENT '冗余.指标类别表（Indicator_Category）属性Category_Encoding',
  `CATEGORY_NAME` varchar(100) DEFAULT NULL COMMENT '冗余.指标类别表（Indicator_Category）属性Category_Name',
  `VALUE` decimal(15,2) DEFAULT NULL COMMENT '计量方法的取值.如指标方向的取值是-1,1 ',
  `OTHERVALUE` decimal(15,2) DEFAULT NULL COMMENT '评分细则存储额外的值,一般指范围取值',
  `VALUE_NAME` varchar(100) DEFAULT NULL COMMENT '指标方向（Indicator_Direction）、最小可能值（Minimum_Possible_Value）、最大可能值（Maximum_Possible_Value）',
  `VALUE_NAME_CODE` varchar(6) DEFAULT NULL COMMENT '指标方向（Indicator_Direction）、最小可能值（Minimum_Possible_Value）、最大可能值（Maximum_Possible_Value）',
  `VALUE_DIRECTION` int DEFAULT NULL COMMENT '指标方向的取值.如指标方向的取值是-1,1 ',
  `OTHERVALUE_DIRECTION` int DEFAULT NULL COMMENT '额外数值对应的评分细则符号(<,=,>)',
  `GRADE` decimal(15,2) DEFAULT NULL COMMENT '评分指标得分',
  `VERSION_NUMBER` int DEFAULT NULL COMMENT '版本号',
  `CREATOR` varchar(100) DEFAULT NULL COMMENT '创建者',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间yyyy-MM-dd hh24:mm:ss',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='评分指标定量方法表';

DROP TABLE IF EXISTS `cr_scoring_indicator`;

CREATE TABLE `cr_scoring_indicator` (
  `ID` varchar(32) NOT NULL COMMENT 'id',
  `PARENT_ID` varchar(32) DEFAULT NULL COMMENT '外键.评分指标表（Scoring_Indicator）的主键',
  `SCORING_INDICATOR_CODE` varchar(4) DEFAULT NULL COMMENT '评分指标的代码',
  `SCORING_INDICATOR_NAME` varchar(100) DEFAULT NULL COMMENT '评分指标的名称',
  `SCORING_INDICATOR_DESCRIPTION` varchar(2000) DEFAULT NULL,
  `Category_Encoding` varchar(4) DEFAULT NULL COMMENT '冗余.指标类别表（Indicator_Category）属性Category_Encoding',
  `CATEGORY_NAME` varchar(100) DEFAULT NULL COMMENT '冗余.指标类别表（Indicator_Category）属性Category_Name',
  `VERSION_NUMBER` int DEFAULT NULL COMMENT '版本号',
  `SCORING_RUBRIC` varchar(2000) DEFAULT NULL,
  `DELETE_FLAG` int DEFAULT NULL COMMENT '删除标志',
  `IS_LAST` int DEFAULT NULL COMMENT '是否为末级指标',
  `DATA_SOURCE_ID` varchar(32) DEFAULT NULL COMMENT '数据源id',
  `DATA_SOURCE_CODE` varchar(32) DEFAULT NULL COMMENT '数据源code',
  `LEVEL_` int DEFAULT NULL COMMENT '指标级别',
  `DATA_SOURCE_NAME` varchar(100) DEFAULT NULL COMMENT '数据源名称',
  `DATA_SOURCE_ORIGIN` varchar(1000) DEFAULT NULL COMMENT '数据来源的来源',
  `STATUS` int DEFAULT NULL COMMENT '状态',
  `CREATOR` varchar(100) DEFAULT NULL COMMENT '创建者',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间yyyy-MM-dd hh24:mm:ss',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='评分指标表';

DROP TABLE IF EXISTS `cr_scoring_org_contrast`;

CREATE TABLE `cr_scoring_org_contrast` (
  `ID` varchar(32) NOT NULL COMMENT 'id',
  `TASK_NO` varchar(32) DEFAULT NULL COMMENT '评价任务编号',
  `COMPUTATIONAL_MODEL_ID` varchar(32) DEFAULT NULL COMMENT '计算模型id',
  `BATCH_NUMBER` varchar(13) DEFAULT NULL COMMENT '批次号',
  `ORG_ID` varchar(32) DEFAULT NULL COMMENT '机构id',
  `ORG_NAME` varchar(200) DEFAULT NULL COMMENT '机构名称',
  `SCORING_INDICATOR_SOLIDIFICATI` varchar(32) DEFAULT NULL COMMENT '评分指标固化id',
  `PARENT_ID` varchar(32) DEFAULT NULL COMMENT '父指标固化id',
  `SCORING_INDICATOR_NAME` varchar(100) DEFAULT NULL COMMENT '评分指标名称',
  `SCORING_INDICATOR_CODE` varchar(100) DEFAULT NULL COMMENT '评分指标代码',
  `SCORING_INDICATOR_DESCRIPTION` varchar(200) DEFAULT NULL COMMENT '评分指标说明',
  `SCORING_INDICATOR_COEFFICIENT` decimal(8,6) DEFAULT NULL COMMENT '评分指标系数',
  `SCORING_ORG_AVG` decimal(8,6) DEFAULT NULL COMMENT '机构指标分',
  `CREATOR` varchar(100) DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(100) DEFAULT NULL COMMENT '更新人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='评分机构评分指标对照表';

DROP TABLE IF EXISTS `cr_task_corp_info`;

CREATE TABLE `cr_task_corp_info` (
  `ID` varchar(32) NOT NULL COMMENT 'id',
  `TASK_NO` varchar(32) DEFAULT NULL COMMENT '评价任务编号',
  `CORP_ID` varchar(32) DEFAULT NULL COMMENT '评价组织',
  `EVALUATE_BY` varchar(100) DEFAULT NULL COMMENT '评价人',
  `STATUS` int DEFAULT NULL COMMENT '状态',
  `CREATOR` varchar(32) DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) DEFAULT NULL COMMENT '更新人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='评价任务和组织表';

DROP TABLE IF EXISTS `cr_task_info`;

CREATE TABLE `cr_task_info` (
  `ID` varchar(32) NOT NULL COMMENT 'id',
  `TASK_NO` varchar(32) DEFAULT NULL COMMENT '评价任务编号',
  `TASK_NAME` varchar(100) DEFAULT NULL COMMENT '评价任务名称',
  `COMPUTATIONAL_MODEL_ID` varchar(100) DEFAULT NULL COMMENT '模板id',
  `TEMPLATE_NAME` varchar(100) DEFAULT NULL COMMENT '评价模板名称',
  `STATUS` int DEFAULT NULL COMMENT '状态',
  `TASK_CYCLE` varchar(20) DEFAULT NULL COMMENT '评价周期',
  `TASK_WEIGHT` varchar(20) DEFAULT NULL COMMENT '评价组织权重',
  `RMK` varchar(2000) DEFAULT NULL,
  `EVALUATE_START_DATE` datetime DEFAULT NULL COMMENT '评价开始日期',
  `EVALUATE_END_DATE` datetime DEFAULT NULL COMMENT '评价结束日期',
  `EVALUATE_CNT` int DEFAULT NULL COMMENT '组织评价次数',
  `ORG_TYPE` varchar(100) DEFAULT NULL COMMENT '机构类别',
  `CREATOR` varchar(32) DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) DEFAULT NULL COMMENT '更新人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `INDEX_TASK_NO` (`TASK_NO`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='任务评价主表';

DROP TABLE IF EXISTS `cr_task_org_info`;

CREATE TABLE `cr_task_org_info` (
  `ID` varchar(32) NOT NULL COMMENT 'id',
  `TASK_NO` varchar(32) DEFAULT NULL COMMENT '评价任务编号',
  `ORG_ID` varchar(32) DEFAULT NULL COMMENT '评价机构',
  `ORG_NAME` varchar(100) DEFAULT NULL COMMENT '机构名称',
  `ORG_AVG` decimal(15,2) DEFAULT NULL COMMENT '评价等级',
  `ORG_EVALUATE_LEVEL` varchar(10) DEFAULT NULL COMMENT '评价等级',
  `STATUS` int DEFAULT NULL COMMENT '状态',
  `CREATOR` varchar(32) DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) DEFAULT NULL COMMENT '更新人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='机构和评价任务主表';

DROP TABLE IF EXISTS `crt_scoring_corp_contrast`;

CREATE TABLE `crt_scoring_corp_contrast` (
  `ID` varchar(32) DEFAULT NULL COMMENT 'ID',
  `TASK_NO` varchar(32) DEFAULT NULL COMMENT '任务编号',
  `COMPUTATIONAL_MODEL_ID` varchar(32) DEFAULT NULL COMMENT '计算模型id',
  `BATCH_NUMBER` varchar(13) DEFAULT NULL COMMENT '批次号',
  `CORP_ID` varchar(32) DEFAULT NULL COMMENT '组织id',
  `SCORING_INDICATOR_SOLIDIFICATI` varchar(32) DEFAULT NULL COMMENT '评分指标固化id',
  `PARENT_ID` varchar(32) DEFAULT NULL COMMENT '父指标固化id',
  `SCORING_INDICATOR_NAME` varchar(100) DEFAULT NULL COMMENT '评分指标名称',
  `SCORING_INDICATOR_CODE` varchar(100) DEFAULT NULL COMMENT '评分指标代码',
  `SCORING_RUBRIC` varchar(1000) DEFAULT NULL COMMENT '评分细则标题',
  `SCORING_INDICATOR_DESCRIPTION` varchar(200) DEFAULT NULL COMMENT '评分指标说明',
  `IS_ADD_OR_SUB_GRADE_NAME` varchar(100) DEFAULT NULL COMMENT '是否额外加减分项',
  `IS_AUTO_SCORING` decimal(8,6) DEFAULT NULL COMMENT '是否自动评分',
  `SCORING_METHOD` decimal(8,6) DEFAULT NULL COMMENT '评分方法',
  `SCORING_INDICATOR_COEFFICIENT` decimal(8,6) DEFAULT NULL COMMENT '评分指标系数',
  `LEVEL_` decimal(8,6) DEFAULT NULL COMMENT '指标层级',
  `CREATOR` varchar(100) DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期时间',
  `INDEX_PROPERTY` decimal(8,6) DEFAULT NULL COMMENT '指标性质',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='评分主体评分指标对照表';

DROP TABLE IF EXISTS `data_source_category`;

CREATE TABLE `data_source_category` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `DATA_SOURCE_CATEGORY_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据来源类别名称',
  `DATA_SOURCE_CATEGORY_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据来源类别代码:D001-供应商;D002-子企业;D003-机构',
  `CREATOR` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '创建人',
  `CREATE_DATE` date NOT NULL COMMENT '创建日期时间:yyyy-MM-dd hh24:mm:ss',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='数据来源类别';

DROP TABLE IF EXISTS `df_business_type`;

CREATE TABLE `df_business_type` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `business_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `business_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `is_valid` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `df_cost_type`;

CREATE TABLE `df_cost_type` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `cost_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `cost_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `is_valid` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `is_init` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `df_direct_finance_info`;

CREATE TABLE `df_direct_finance_info` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `bill_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `status` decimal(10,0) DEFAULT NULL,
  `corp_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `is_budget` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `stock_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `stock_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `start_date` datetime DEFAULT NULL,
  `cur_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `bond_rating` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `bond_main_rating` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `peroid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `unit` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `money` decimal(18,2) DEFAULT NULL,
  `surplus_money` decimal(18,2) DEFAULT NULL,
  `doc_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `listing_date` datetime DEFAULT NULL,
  `end_date` datetime DEFAULT NULL,
  `is_resale_terms` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `resale_date` datetime DEFAULT NULL,
  `is_redemption_provision` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `redemption_provision_date` datetime DEFAULT NULL,
  `listing_place` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `purpose` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `df_business_type_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `release_main_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `release_main_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `leader_underwriter` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `underwriter` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `rmk` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `coupon_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `frequency_interest_payments` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `face_interest_rate` decimal(8,6) DEFAULT NULL,
  `float_interest_rat` decimal(8,6) DEFAULT NULL,
  `interest_rat` decimal(8,6) DEFAULT NULL,
  `composite_cost_rate` decimal(8,6) DEFAULT NULL,
  `composite_cost` decimal(18,2) DEFAULT NULL,
  `create_date` datetime DEFAULT NULL,
  `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `update_date` datetime DEFAULT NULL,
  `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `upload_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `cur_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别名称',
  `corp_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `df_direct_finance_repay`;

CREATE TABLE `df_direct_finance_repay` (
