  `rmk` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `corp_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `create_date` datetime DEFAULT NULL,
  `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `update_date` datetime DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `df_direct_finance_repay_tmp`;

CREATE TABLE `df_direct_finance_repay_tmp` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `bill_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `direct_finance_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `repay_date` datetime DEFAULT NULL,
  `repay_money` decimal(18,2) DEFAULT NULL,
  `interest` decimal(18,2) DEFAULT NULL,
  `service_charge` decimal(18,2) DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `df_intermediate_cost`;

CREATE TABLE `df_intermediate_cost` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `direct_finance_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `cost_type_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `rate` decimal(8,6) DEFAULT NULL,
  `advance_fees` decimal(18,2) DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `df_third_party_agency`;

CREATE TABLE `df_third_party_agency` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `direct_finance_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `agency_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `agency_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `distributed_lock`;

CREATE TABLE `distributed_lock` (
  `lock_key` char(20) NOT NULL,
  `lock_value` varchar(20) NOT NULL,
  `expire` bigint DEFAULT NULL,
  PRIMARY KEY (`lock_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

DROP TABLE IF EXISTS `doc_invoice`;

CREATE TABLE `doc_invoice` (
  `ID` varchar(32) NOT NULL,
  `CODE` varchar(20) DEFAULT NULL COMMENT '发票代码',
  `TYPE` varchar(10) DEFAULT NULL COMMENT '发票类型',
  `NUMBER` varchar(12) DEFAULT NULL COMMENT '发票编号',
  `PAR_AMT` decimal(19,2) DEFAULT NULL COMMENT '票面金额',
  `TAXINC_AMT` decimal(19,2) DEFAULT NULL COMMENT '不含税金额',
  `CHECK_CODE` varchar(30) DEFAULT NULL COMMENT '发票校验码',
  `DRA_DATE` datetime DEFAULT NULL COMMENT '开票日期',
  `BILL_ID` varchar(32) NOT NULL COMMENT '挂接业务ID',
  `BILL_NO` varchar(20) DEFAULT NULL COMMENT '挂接业务编号',
  `CREATE_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(50) DEFAULT NULL COMMENT '更新人',
  `UPDATE_DATE` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `TENANT_ID` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=COMPACT COMMENT='应收款管理-发票信息表';

DROP TABLE IF EXISTS `doc_manage`;

CREATE TABLE `doc_manage` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位',
  `CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单据编号',
  `BATCH_BUS_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '业务类型',
  `SOURCE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单据来源',
  `VOUCHER_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '结算方式',
  `RECEIPT_DATE` datetime NOT NULL COMMENT '单据日期',
  `END_DATE` datetime NOT NULL COMMENT '到期日期',
  `AGING_DATE` datetime NOT NULL COMMENT '账龄起算日期',
  `PAYEE_ACC` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账号',
  `PAYEE_ACC_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款账户名',
  `PAYEE_BANK_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款方开户行行号',
  `PAYEE_BANK_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款开户行名称',
  `RECEIVABLE_MONEY` decimal(19,2) NOT NULL COMMENT '应收金额',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应收币种',
  `EXRATE_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '汇率类型',
  `CONVERT_PRE_MONEY` decimal(19,2) DEFAULT NULL COMMENT '折算金额',
  `PAYER_ACC_NO` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款账号',
  `PAYER_ACC_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款账号名称',
  `PAYER_BANK_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款开户行名称',
  `PAYER_BANK_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款开户行行号',
  `EXTERNAL_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '客商名称',
  `EXTERNAL_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '客商类型',
  `EXTERNAL_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客商编号',
  `CONTRACT_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '合同编号',
  `CONTRACT_NAME` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '合同名称',
  `CONTRACT_Money` decimal(19,2) DEFAULT NULL COMMENT '合同金额',
  `CONTRACT_DATE` datetime DEFAULT NULL COMMENT '合同日期',
  `WRITE_OFF_STATUS` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '核销状态',
  `WRITE_OFF_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '核销类型',
  `BEFORE_WRITE_OFF_STATUS` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '核销前状态',
  `WRITE_OFF_BAL` decimal(19,2) DEFAULT NULL COMMENT '应收单据余额',
  `REASON_TITLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '变更作废原因标题',
  `REASON_CONTENT` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '变更作废原因内容',
  `ATTACHMENT_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发票附件',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人',
  `UPDATE_DATE` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  `REASON_STATUS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '变更作废状态',
  `CONTRACT_ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '合同附件ID',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='应收款管理-应收单据信息表';

DROP TABLE IF EXISTS `doc_overdue_notice`;

CREATE TABLE `doc_overdue_notice` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `DOC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应收单据ID',
  `COLLECTION_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '催收人',
  `COLLECTION_DATE` date DEFAULT NULL COMMENT '催收时间',
  `OVERDUE_REASON` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '逾期原因',
  `COLLECTIO_RESULT` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '催收结果',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` date DEFAULT NULL COMMENT '创建时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='应收单逾期催收登记表';

DROP TABLE IF EXISTS `doc_wirte_off_relation`;

CREATE TABLE `doc_wirte_off_relation` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `BATCH_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '核销批次号',
  `CANCEL_BATCH_NO` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '取消核销对应批次号',
  `DOC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '应收单据ID',
  `RELATION_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '关联数据ID',
  `PAYMENT_MEANS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '结算方式',
  `RULES_NAME` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '匹配规则描述',
  `EXCHANGE_RATE` decimal(15,4) DEFAULT NULL COMMENT '本次核销汇率',
  `RELATION_ORIGIN_MONEY` decimal(19,2) DEFAULT NULL COMMENT '可核销原币金额',
  `RELATION_CONVERT_MONEY` decimal(19,2) DEFAULT NULL COMMENT '可核销应收币种金额',
  `BEFORE_WRITE_OFF_BAL` decimal(19,2) DEFAULT NULL COMMENT '核销前金额',
  `FORCE_REASON_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '强制核销类型',
  `FORCE_PAYMENT_MEANS` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收入结算方式',
  `FORCE_REASON` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '核销原因',
  `WRITE_OFF_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '核销类型',
  `WRITE_OFF_STATUS` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '核销状态',
  `BEFORE_WRITE_OFF_STATUS` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '核销前状态',
  `WRITE_OFF_NUM` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '核销笔数 11一对一，12一对多，21多对一，10强制核销',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '审批状态',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  `EXECUTE_MONEY` decimal(19,2) DEFAULT NULL COMMENT '执行金额',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='应收单据核销关系表';

DROP TABLE IF EXISTS `dsl_inteface_flag`;

CREATE TABLE `dsl_inteface_flag` (
  `ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键id',
  `SOURCE_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '外表主键',
  `RETURN_MESSAGE` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'ERP系统返回消息',
  `RETURN_CODE` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'ERP系统返回状态',
  `TABLE_SOURCE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据源标识',
  `OP_TIME` datetime DEFAULT NULL COMMENT 'ERP系统返回信息时间',
  `SYNC_STATUS` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据发送状态 F失败 S成功',
  `REVERSE1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备用字段1',
  `REVERSE2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备用字段2',
  `REVERSE3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备用字段3',
  `REVERSE4` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备用字段4',
  `REVERSE5` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备用字段5',
  `SOURCE_NUM` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '全量流水接口共享单号字段',
  `TENANT_ID` varchar(32) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_DSL_INTEFACE_FLAG_SOURCE_ID` (`SOURCE_ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `dsl_interface_log`;

CREATE TABLE `dsl_interface_log` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键id',
  `SOURCE_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '来源主键',
  `TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '日志类型（1:成功、0:失败）',
  `INTERFACE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口名称',
  `INTERFACE_CODE` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口编号',
  `LOG_TIME` datetime DEFAULT NULL COMMENT '日志时间',
  `LOG` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '接口日志',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `INDEX_INTERFACE_CODE` (`INTERFACE_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='ERP接口日志表';

DROP TABLE IF EXISTS `e_accept_bill`;

CREATE TABLE `e_accept_bill` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'id',
  `BILL_NO` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '电子回单号码',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位ID',
  `BILL_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '电子回单类型16-承兑汇票电子回单',
  `PAYER_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款人名称',
  `PAYER_ACC` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '付款人账号',
  `PAYER_BANK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '付款人开户行',
  `PAYEE_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ACC` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人账号',
  `PAYEE_BANK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '收款人开户行',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别',
  `PAY_MONEY` decimal(15,2) NOT NULL COMMENT '金额',
  `PURPOSE` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用途',
  `PAY_TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '结算方式',
  `ACCRUAL_DATE` datetime DEFAULT NULL COMMENT '起息日期',
  `TALLY_DATE` datetime DEFAULT NULL COMMENT '记账日期',
  `TALLIER_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记账员',
  `VOUCHER_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '凭证号',
  `OLD_VOUCHER` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原始凭证号',
  `OLD_VOUCHER_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原始凭证名称',
  `OLD_VOUCHER_MONEY` decimal(15,2) DEFAULT NULL COMMENT '原凭证金额',
  `DEBIT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '借方科目',
  `CREDIT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '贷方科目',
  `DEBIT1` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '借方科目1',
  `CREDIT1` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '贷方科目1',
  `ACCESSORY` decimal(10,0) DEFAULT NULL COMMENT '贴现利息收入',
  `REMARK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附言',
  `ENCRY_DATE` datetime DEFAULT NULL COMMENT '产生编码日期',
  `RANDOM` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '加密随机数',
  `ENCRY_SOURCE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '编码源',
  `SUBSCRIBER` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'subscriber',
  `VALIDATE_CODE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '验证码',
  `IS_VALIDATE` decimal(2,0) DEFAULT NULL COMMENT '验证标志10-已验证11-验证失败12-未验证默认为12',
  `VALID_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '验证人',
  `VALID_DATE` datetime DEFAULT NULL COMMENT '验证时间',
  `PRINTS` decimal(10,0) DEFAULT NULL COMMENT '打印次数',
  `STATUS` decimal(10,0) NOT NULL COMMENT '状态1，新输入-1，删除2，冲帐',
  `CHECKER_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '复核员',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `OLD_VOUCHER_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='承兑汇票电子回单表\n16-承兑汇票电子回单';

DROP TABLE IF EXISTS `e_accrual_bill`;

CREATE TABLE `e_accrual_bill` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'id',
  `BILL_NO` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '电子回单号A+年年月月日日+6位序列号(从000001开始)',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位ID',
  `BILL_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '电子回单类型01-存款利息单02-贷款利息单03-委托贷款利息清单04-定期利息单05-通知利息单19-活期保证金利息单20-定期保证金利息单',
  `TALLY_DATE` datetime DEFAULT NULL COMMENT '利息产生日期（记账日期）',
  `ACC_NO` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '账号',
  `ACC_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '户名',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '币别',
  `START_DATE` datetime NOT NULL COMMENT '开始日期',
  `END_DATE` datetime NOT NULL COMMENT '结束日期',
  `ACCRUAL` decimal(15,2) DEFAULT NULL COMMENT '利息',
  `CUMU` decimal(18,2) DEFAULT NULL COMMENT '积数',
  `INTEREST` decimal(14,6) DEFAULT NULL COMMENT '利率',
  `DAYS` decimal(10,0) DEFAULT NULL COMMENT '天数',
  `OTHER_SUBJECT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '对方科目',
  `HOME_SUBJECT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '本方科目',
  `MONEY` decimal(18,2) DEFAULT NULL COMMENT '本金',
  `NUMMONEY` decimal(18,2) DEFAULT NULL COMMENT '本息合计',
  `VOUCHER_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '凭证号',
  `RMK` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '备注',
  `ENCRY_DATE` datetime DEFAULT NULL COMMENT '产生编码日期',
  `RANDOM` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '加密随机数',
  `ENCRY_SOURCE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '编码源',
  `SUBSCRIBER` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'subscriber',
  `VALIDATE_CODE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '验证码',
  `IS_VALIDATE` decimal(2,0) DEFAULT NULL COMMENT '验证标志10-已验证11-验证失败12-未验证默认为12',
  `VALID_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '验证人',
  `VALID_DATE` datetime DEFAULT NULL COMMENT '验证时间',
  `PRINTS` decimal(10,0) DEFAULT NULL COMMENT '打印次数',
  `STATUS` decimal(10,0) NOT NULL COMMENT '状态1，新输入-1，删除2，冲帐',
  `CHECKER_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '复核员',
  `INTEREST_DTL_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '利息清单明细ID',
  `TALLIER_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记账员',
  `TOTOL_MONEY` decimal(18,2) DEFAULT NULL COMMENT '合同金额',
  `REPAY_MONEY` decimal(18,2) DEFAULT NULL COMMENT '已还款金额',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ORIG_VOUCHER_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ORIG_VOUCHER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SUMMARY_CONTENT` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `INDEX_E_ACCRUAL_BILL` (`CORP_ID`,`BILL_NO`) USING BTREE,
  KEY `IND_ENCRY_DATE_ACCRUAL` (`ENCRY_DATE`) USING BTREE,
  KEY `IDX_E_ACCRUAL_BILL_BT` (`BILL_TYPE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='利息清单电子回单\n01-存款利息单\n02-贷款利息单\n03-委托贷款利息清单\n04-定期利息单\n05-通知利息单\n19-活期保证金利息单\n20-定期保证金利息单';

DROP TABLE IF EXISTS `e_bill_message`;

CREATE TABLE `e_bill_message` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ENROL_DATE` datetime NOT NULL COMMENT '录入时间',
  `BILL_NO` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '电子回单号',
  `OP` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作人员',
  `OP_NAME` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作人员姓名',
  `OP_TYPE` decimal(10,0) NOT NULL COMMENT '操作类型OP_TYPE =1 表示生成数据OP_TYPE =2 表示作废数据OP_TYPE =3 表示删除数据OP_TYPE =4 表示打印数据',
  `MESSAGE` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '消息',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='电子回单消息表';

DROP TABLE IF EXISTS `e_bill_print`;

CREATE TABLE `e_bill_print` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `BILL_NO` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '电子回单号',
  `PRINTS` decimal(10,0) NOT NULL COMMENT '打印次数',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位id',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_PRINT_BILL_NO` (`BILL_NO`) USING BTREE,
  KEY `IDX_PRINT_CORP_ID` (`CORP_ID`) USING BTREE,
  KEY `IDX_E_BILL_PRINT_BN_P` (`BILL_NO`,`PRINTS`) USING BTREE,
  KEY `IDX_E_BILL_PRINT_CI_BN_P` (`CORP_ID`,`BILL_NO`,`PRINTS`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='电子回单打印';

DROP TABLE IF EXISTS `e_compare_bill`;

CREATE TABLE `e_compare_bill` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'id',
  `BILL_NO` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'billNo',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位ID',
  `BILL_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '电子回单类型17-对账单电子回单',
  `ACC_NO` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '内部账号',
  `ACC_NAME` varchar(90) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '账户名称',
  `SUMMARY_COMMENT` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT 'summaryComment',
  `TALLYER_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记账员',
  `TALLY_DATE` datetime DEFAULT NULL COMMENT 'tallyDate',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币别',
  `BILL_CODE` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '对账单票据号码',
  `INTEREST_START_DATE` datetime DEFAULT NULL COMMENT 'interestStartDate',
  `DEBIT_MONEY` decimal(15,2) DEFAULT NULL COMMENT '借方金额',
  `CREDIT_MONEY` decimal(38,2) DEFAULT NULL COMMENT '贷方金额',
  `BALANCE` decimal(15,2) DEFAULT NULL COMMENT '余额',
  `VOUCHER_NO` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '凭证号',
  `REDBLUE_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '红蓝标志（R -红，B 蓝）',
