  `MATCH_FIELD_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '自定义字段中为标记为匹配的字段的ID',
  `ORDERNUM` decimal(4,0) DEFAULT NULL COMMENT '排序字段',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
