  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `fbs_item`;

CREATE TABLE `fbs_item` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主建',
  `ITEM_CODE` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '科目代码',
  `ITEM_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '科目名称',
  `SUPER_ITEM_CODE` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '父科目',
  `LEVELS` decimal(5,0) DEFAULT NULL COMMENT '科目层级',
  `SIGN` decimal(5,0) DEFAULT NULL COMMENT '资金流向1， 资金流入-1 ，资金流出',
  `IS_INTERNAL` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '是否冲抵科目  1-是 0-否',
  `IS_CONTROL` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否计划控制科目 1-是 0-否',
  `IS_RIGID` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否刚性科目 1-是 0-否',
  `IS_BEGIN_PERIOD` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否期初科目 1-是 0-否',
  `IS_END_PERIOD` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否期末科目 1-是 0-否',
  `VALID_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '有效标志 0 无效 1 有效',
  `ITEM_RELATION` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `OVER_PER_SPEND` decimal(10,2) DEFAULT NULL COMMENT '超计划比例',
  `RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `IS_SYSTEM` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否系统科目（系统科目不能删除）系统科目：100-期初资金，200-资金增加，300-可用资金，400-资金减少，500-资金不足或多余，600-新增筹资或还款，700-期末资金，800表外科目',
  `seq_code` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SUPER_ITEM_CODES` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '存父的所有的编码,用逗号分隔',
  `IS_WRITE` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否允许填写计划 1-是 0-否',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CASH_ITEM_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CASH_ITEM_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ALLOT_ITEM_CODE` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_WRITE_DETAIL` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_FBS_ITEM_IC` (`ITEM_CODE`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='计划科目表';

DROP TABLE IF EXISTS `fbs_message`;

CREATE TABLE `fbs_message` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ENTER_DATE` datetime NOT NULL COMMENT '录入时间',
  `BILL_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单据号',
  `OP` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作人员',
  `OP_NAME` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作人员姓名',
  `MESSAGE_TYPE` decimal(10,0) NOT NULL COMMENT '操作类型',
  `MESSAGE` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '消息',
  `BUS_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '业务名称 如计划上报 计划追加 计划执行',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='计划日志表';

DROP TABLE IF EXISTS `fbs_process_rule`;

CREATE TABLE `fbs_process_rule` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `PROCESS_RULE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SORT` int DEFAULT NULL,
  `PROCESS_RATIO` decimal(10,4) DEFAULT NULL,
  `VALID_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '1',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime(6) DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime(6) DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='计划执行规则表';

DROP TABLE IF EXISTS `fbs_salesreturn_analyse`;

CREATE TABLE `fbs_salesreturn_analyse` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位ID',
  `BEGIN_DATE` datetime NOT NULL COMMENT '计划日期',
  `OPP_ACC_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户名称',
  `PLAN_CASH_MONEY` decimal(15,2) DEFAULT NULL COMMENT '计划现金回款',
  `PLAN_BILL_MONEY` decimal(15,2) DEFAULT NULL COMMENT '计划票据回款',
  `FACT_CASH_MONEY` decimal(15,2) DEFAULT NULL COMMENT '实际现金回款',
  `FACT_BILL_MONEY` decimal(15,2) DEFAULT NULL,
  `DIFF_REASON` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '差异原因',
  `ANALYSE_STATUS` decimal(10,0) DEFAULT NULL COMMENT '差异状态',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人登录名称',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人登录名称',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新日期',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='销售回款差异分析表';

DROP TABLE IF EXISTS `fc_acc`;

CREATE TABLE `fc_acc` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'id',
  `BLNCTR_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '结算中心账号',
  `ACC_NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NET_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '网点ID',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '开户单位ID',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '币别代码',
  `SUBJECT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '科目代码',
  `ACC_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '账户类别',
  `ATTRIBUTE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '账户属性',
  `NATURE_CODE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '账户性质',
  `BANK_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行代码',
  `BALANCE_WAY` decimal(1,0) NOT NULL COMMENT '余额方向',
  `INTEREST_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '计息标志 ',
  `INTEREST_START_DATE` datetime DEFAULT NULL COMMENT '起息日期',
  `INTEREST_RATE` decimal(8,6) DEFAULT NULL COMMENT '利率',
  `OVERDRAFT_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '透支标志',
  `OVERDRAFT_RATE` decimal(8,6) DEFAULT NULL COMMENT '透支利率',
  `OVERDRAFT_MONEY` decimal(14,2) DEFAULT NULL COMMENT '透支金额',
  `CONTRACT_NO` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '合同编号',
  `DEADLINE_DATE` datetime DEFAULT NULL COMMENT '到期日期',
  `DELAY_DEADLINE_DATE` datetime DEFAULT NULL COMMENT '展期到期日期',
  `OVERDUE_RATE` decimal(8,6) DEFAULT NULL COMMENT '逾期利率',
  `ACC_FOR_DEDUCT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '扣息活期存款账户',
  `DEDUCT_MODE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '扣息方式',
  `NOTIFY_TYPE` decimal(5,0) DEFAULT NULL COMMENT '通知类型(期限)',
  `ACC_STATE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '账户状态',
  `AGREED_DEPOSIT_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '协定存款标志',
  `PREDRAW_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '预提标志',
  `IF_COMPARE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否产生对账数据',
  `ACC_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '往来账号',
  `ACC_START_DATE` datetime DEFAULT NULL COMMENT '账号启用日期',
  `OPERATOR_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '经办人代码',
  `ACC_OPEN_TIME` datetime NOT NULL COMMENT '开户日期',
  `CHECKER_CODE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '复核员代码',
  `CHECK_TIME` datetime DEFAULT NULL COMMENT '复核日期',
  `AREA_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '区域代码',
  `VOCATION_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '行业代码',
  `SHORTCUT` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UNION_NET` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '联行网点',
  `DELAY_RATE` decimal(8,6) DEFAULT NULL COMMENT '展期利率',
  `UNION_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '联行账号',
  `PRECATION_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '委托贷款帐号',
  `PRECATION_CORP` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '委托贷款方',
  `POUNDAGE_RATE` decimal(8,6) DEFAULT NULL COMMENT '委托存款的手续费率',
  `CHARGE_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '手续费收取账户',
  `TRANSACT_WAY` decimal(2,0) DEFAULT NULL COMMENT '办理方式',
  `CANCEL_DATE` datetime DEFAULT NULL COMMENT '销户日期',
  `VALID_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '有效标志',
  `CHECK_BACK_REASON` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '打回原因',
  `END_UNIT` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '到期单位',
  `CERTIFICATE_WAY` decimal(2,0) DEFAULT NULL COMMENT '到期续存方式',
  `HANDLE_CHARGE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否收取手续费',
  `ACC_CUSSENT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '贷款账号',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `POOL_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `RELATION_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RMK` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `REFERENCE_RATE_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0',
  `INTEREST_IN_EXP` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `INTEREST_REC_PAY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `UK_BLNCTRACC_TENANTID` (`BLNCTR_ACC`,`TENANT_ID`),
  KEY `IDX_FC_ACC_ACC` (`BLNCTR_ACC`) USING BTREE,
  KEY `IDX_FC_ACC_SUBJECT_ID` (`SUBJECT_ID`) USING BTREE,
  KEY `idx_fc_acc_acc_corp` (`BLNCTR_ACC`,`CORP_ID`),
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='内部账户信息表';

DROP TABLE IF EXISTS `fc_acc_balance`;

CREATE TABLE `fc_acc_balance` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键ID',
  `BALANCE_DATE` datetime NOT NULL COMMENT '余额日期',
  `ACCOUNT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '账号',
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '币别代码',
  `ACC_NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TR_CNT` decimal(10,0) NOT NULL COMMENT '内转笔数',
  `RUSH_CNT` decimal(10,0) NOT NULL COMMENT '冲正笔数',
  `CNT` decimal(10,0) NOT NULL COMMENT '笔数',
  `YESTER_BALANCE` decimal(15,2) DEFAULT NULL COMMENT '昨日余额',
  `BALANCE` decimal(15,2) NOT NULL COMMENT '余额',
  `TR_DEBIT_MONEY` decimal(15,2) NOT NULL COMMENT '内转借方发生额',
  `TR_CREDIT_MONEY` decimal(15,2) NOT NULL COMMENT '内转贷方发生额',
  `RUSH_DEBIT_MONEY` decimal(15,2) NOT NULL COMMENT '冲正借方发生额',
  `RUSH_CREDIT_MONEY` decimal(15,2) NOT NULL COMMENT '冲正贷方发生额',
  `DEBIT_MONEY` decimal(15,2) NOT NULL COMMENT '借方发生额',
  `CREDIT_MONEY` decimal(15,2) NOT NULL COMMENT '贷方发生额',
  `TALLY_DAY_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '是否记账日',
  `DEBIT_CNT` decimal(10,0) DEFAULT NULL COMMENT '借方笔数',
  `CREDIT_CNT` decimal(10,0) DEFAULT NULL COMMENT '贷方笔数',
  `FREEZE_MONEY` decimal(15,2) DEFAULT NULL COMMENT '冻结金额',
  `CREATE_TIME` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NET_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '网点ID',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_FC_ACC_BALANCE` (`ACCOUNT`,`BALANCE_DATE`) USING BTREE,
  KEY `idx_fc_acc_balance_acc_cur_date` (`ACCOUNT`,`CUR_ID`,`BALANCE_DATE`),
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='账户批量余额表';

DROP TABLE IF EXISTS `fc_acc_history`;

CREATE TABLE `fc_acc_history` (
  `ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `FCACC_ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BLNCTR_ACC` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACC_NAME` varchar(1500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NET_ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CORP_ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CUR_ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SUBJECT_ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACC_TYPE` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ATTRIBUTE_ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NATURE_CODE_ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BANK_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BALANCE_WAY` decimal(2,0) DEFAULT NULL,
  `INTEREST_SIGN` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `INTEREST_START_DATE` datetime DEFAULT NULL,
  `INTEREST_RATE` decimal(10,6) DEFAULT NULL,
  `OVERDRAFT_SIGN` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `OVERDRAFT_RATE` decimal(10,6) DEFAULT NULL,
  `OVERDRAFT_MONEY` decimal(16,6) DEFAULT NULL,
  `CONTRACT_NO` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `DEADLINE_DATE` datetime DEFAULT NULL,
  `DELAY_DEADLINE_DATE` datetime DEFAULT NULL,
  `OVERDUE_RATE` decimal(10,0) DEFAULT NULL,
  `ACC_FOR_DEDUCT` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `DEDUCT_MODE` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NOTIFY_TYPE` decimal(6,0) DEFAULT NULL,
  `ACC_STATE` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `AGREED_DEPOSIT_SIGN` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PREDRAW_SIGN` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IF_COMPARE` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACC_ID` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACC_START_DATE` datetime DEFAULT NULL,
  `OPERATOR_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACC_OPEN_TIME` datetime DEFAULT NULL,
  `CHECKER_CODE` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHECK_TIME` datetime DEFAULT NULL,
  `AREA_CODE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VOCATION_CODE` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SHORTCUT` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UNION_NET` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `DELAY_RATE` decimal(10,0) DEFAULT NULL,
  `UNION_ACC` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PRECATION_ACC` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PRECATION_CORP` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `POUNDAGE_RATE` decimal(10,0) DEFAULT NULL,
  `CHARGE_ACC` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TRANSACT_WAY` decimal(3,0) DEFAULT NULL,
  `CANCEL_DATE` datetime DEFAULT NULL,
  `VALID_SIGN` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CHECK_BACK_REASON` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `END_UNIT` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CERTIFICATE_WAY` decimal(3,0) DEFAULT NULL,
  `HANDLE_CHARGE` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ACC_CUSSENT` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `POOL_SIGN` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RELATION_ACC` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RMK` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
