DROP TABLE IF EXISTS `fc_acc_month_balance`;

CREATE TABLE `fc_acc_month_balance` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键ID',
  `YEAR_MONTH2` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '年月',
  `ACCOUNT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '账号',
  `ACC_NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TR_CNT` decimal(10,0) NOT NULL COMMENT '内转笔数',
  `RUSH_CNT` decimal(10,0) NOT NULL COMMENT '冲正笔数',
  `CNT` decimal(10,0) NOT NULL COMMENT '笔数',
  `TR_DEBIT_MONEY` decimal(15,2) NOT NULL COMMENT '内转借方发生额',
  `TR_CREDIT_MONEY` decimal(15,2) NOT NULL COMMENT '内转贷方发生额',
  `RUSH_DEBIT_MONEY` decimal(15,2) NOT NULL COMMENT '冲正借方发生额',
  `RUSH_CREDIT_MONEY` decimal(15,2) NOT NULL COMMENT '冲正贷方发生额',
  `DEBIT_MONEY` decimal(15,2) NOT NULL COMMENT '借方发生额',
  `CREDIT_MONEY` decimal(15,2) NOT NULL COMMENT '贷方发生额',
