DROP TABLE IF EXISTS `fc_union_accbook`;

CREATE TABLE `fc_union_accbook` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键ID',
  `SEND_NET` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '发送方网点',
  `SEND_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '发送方账号',
  `SEND_VOUCHER` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '发送方凭证号',
  `WAY` decimal(1,0) NOT NULL COMMENT '记账方向',
  `SEND_MONEY` decimal(15,2) NOT NULL COMMENT '金额',
  `SUMMARY_CONTENT` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '摘要',
  `VOUCHER_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '凭证种类',
  `RECEIVE_NET` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '接收方网点',
  `RECEIVE_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接收方账号',
  `EXTERNAL_CORP` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外单位',
  `EXTERNAL_ACC` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外单位账号',
  `BANK` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外单位开户行',
  `EXTERNAL_PROV` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外单位信息省',
  `EXTERNAL_CITY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外单位信息市',
  `RECEIVE_ORDER` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接收方流水号',
  `BILL_STATE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '往来状态',
  `START_CORP` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '委托收款的收款单位',
  `START_CORP_ACC` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '委托收款的收款账号',
  `START_BANK` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '委托收款的收款银行',
  `RETURN_MSG` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '返回信息',
  `SEND_VOUCHER_DATE` datetime DEFAULT NULL COMMENT '发送凭证日期',
  `SEND_BUS_GLOBAL_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BUS_ORI_TYPE` decimal(2,0) DEFAULT NULL COMMENT '业务来源类型',
