  `MODEL_BATCH_ID` varchar(32) DEFAULT NULL COMMENT '模型批次id',
  `CATEGORY_NAME` varchar(100) DEFAULT NULL COMMENT '类别名称',
  `CATEGORY_ENCODING` varchar(4) DEFAULT NULL COMMENT '类别代码',
  `CATEGORY_DESCRIPTION` varchar(200) DEFAULT NULL COMMENT '类别说明',
  `CREATOR` varchar(100) DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
