  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`widget_id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `ownership_structure_data`;

CREATE TABLE `ownership_structure_data` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `INVESTOR` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出资人',
  `FINANCING_WAY` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '融资方式',
  `INVESTMENT_METHOD` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '出资方式',
  `CONTRIBUTION_AMOUNT` decimal(15,4) DEFAULT '0.0000' COMMENT '出资金额',
  `SHAREHOLDING_RATIO` decimal(6,4) DEFAULT '0.0000' COMMENT '持股比例',
  `ASSET_NAME` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '资产名称',
  `INSTITUTIONAL_RAW_DATA_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外键（机构原始数据）ID',
  `RMK` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `CREATOR` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '创建人',
  `CREATE_DATE` date NOT NULL COMMENT '创建日期时间:yyyy-MM-dd hh24:mm:ss',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='股权结构数据';

DROP TABLE IF EXISTS `payment_consumer_record`;

CREATE TABLE `payment_consumer_record` (
  `MSG_ID` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '消息ID',
  `BUSINESS_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '业务类型',
  `BUSINESS_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '业务ID',
  `MESSAGE` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '消息内容',
  `MSG_HANDLE_STATUS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '消息处理状态',
  `EXCEPTION_MSG` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '异常日志',
  `CREATE_TIME` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `UPDATE_TIME` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`MSG_ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='消费者消息记录表(监听核算推送给结算的消息)';

DROP TABLE IF EXISTS `payment_producer_record`;

CREATE TABLE `payment_producer_record` (
  `MSG_ID` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '消息ID',
  `BUSINESS_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '业务类型',
  `BUSINESS_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '业务ID',
  `EXCHANGE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '交换机名称',
  `ROUTING_KEY` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '路由key',
  `MESSAGE` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '消息内容',
  `SEND_STATUS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '消息投递状态',
  `CREATE_TIME` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建用户ID',
  `UPDATE_TIME` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `UPDATE_BY` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改用户ID',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`MSG_ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='生产者消息记录表(结算发送消息给核算)';

DROP TABLE IF EXISTS `pk_fex_settle_fill_rule_add`;

CREATE TABLE `pk_fex_settle_fill_rule_add` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `RULE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '结算自动填充规则补充表',
  `FIELD_NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '字段名称',
  `FIELD_VAL` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '字段内容',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='结算自动填充规则补充表';

DROP TABLE IF EXISTS `q_m_scoring_i_fix_report`;

CREATE TABLE `q_m_scoring_i_fix_report` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `EVALUATION_REPORT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评估报告主键 评估报告（EVALUATION_REPORT）id',
  `MODEL_BATCH_NUMBER` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '模型批次号 模型批次的批次号',
  `EVALUATION_BATCH_NUMBER` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评估批次号',
  `SCORING_INDICATOR_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标名称 评分指标的名称',
  `SCORING_INDICATOR_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标代码 评分指标的代码',
  `SCORING_INDICATOR_DESCRIPTION` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标说明 评分指标作用说明',
  `CATEGORY_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指标类别名称 冗余.指标类别表（INDICATOR_CATEGORY）属性CATEGORY_NAME',
  `CATEGORY_ENCODING` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指标类别代码 冗余.指标类别表（INDICATOR_CATEGORY）属性CATEGORY_ENCODING',
  `VALUE` decimal(15,2) DEFAULT NULL COMMENT '数值 计量方法的取值.如指标方向的取值是-1,1 ',
  `VALUE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数值名称 指标方向（INDICATOR_DIRECTION）、最小可能值（MINIMUM_POSSIBLE_VALUE）、最大可能值（MAXIMUM_POSSIBLE_VALUE）',
  `VALUE_NAME_CODE` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数值名称代码 指标方向（INDICATOR_DIRECTION）、最小可能值（MINIMUM_POSSIBLE_VALUE）、最大可能值（MAXIMUM_POSSIBLE_VALUE）',
  `S_I_F_R_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外键（报告中评分指标固化主键） 报告中评分指标固化（SCORING_INDICATOR_FIX_REPORT）id',
  `OTHERVALUE` decimal(15,2) DEFAULT NULL COMMENT '额外数值',
  `SCORING_INDICATOR_SOL_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标固化id',
  `QUANTITATIVE_METHOD_FOR_SI_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标定量方法主键',
  `VERSION_NUMBER` decimal(10,0) DEFAULT NULL COMMENT '版本号',
  `VALUE_DIRECTION` decimal(4,0) DEFAULT NULL COMMENT '数值对应得分细则符号',
  `OTHERVALUE_DIRECTION` decimal(4,0) DEFAULT NULL COMMENT '额外数值对应得分细则符号',
  `GRADE` decimal(15,2) DEFAULT NULL COMMENT '得分',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报告中评分指标定量方法固化  评分指标的定量方法,存放评分指标的计量单位和计量的方法,是计算模型中的一部分';

DROP TABLE IF EXISTS `qrtz_job_details`;

CREATE TABLE `qrtz_job_details` (
    `SCHED_NAME` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `JOB_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `JOB_GROUP` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `DESCRIPTION` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
    `JOB_CLASS_NAME` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `IS_DURABLE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `IS_NONCONCURRENT` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `IS_UPDATE_DATA` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `REQUESTS_RECOVERY` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `JOB_DATA` longblob,
    `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
    PRIMARY KEY (`SCHED_NAME`,`JOB_NAME`,`JOB_GROUP`) USING BTREE,
    KEY `IDX_QRTZ_J_GRP` (`SCHED_NAME`,`JOB_GROUP`) USING BTREE,
    KEY `IDX_QRTZ_J_REQ_RECOVERY` (`SCHED_NAME`,`REQUESTS_RECOVERY`) USING BTREE,
    KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `qrtz_triggers`;

CREATE TABLE `qrtz_triggers` (
    `SCHED_NAME` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `TRIGGER_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `TRIGGER_GROUP` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `JOB_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `JOB_GROUP` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `DESCRIPTION` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
    `NEXT_FIRE_TIME` decimal(13,0) DEFAULT NULL,
    `PREV_FIRE_TIME` decimal(13,0) DEFAULT NULL,
    `PRIORITY` decimal(13,0) DEFAULT NULL,
    `TRIGGER_STATE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `TRIGGER_TYPE` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `START_TIME` decimal(13,0) NOT NULL,
    `END_TIME` decimal(13,0) DEFAULT NULL,
    `CALENDAR_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
    `MISFIRE_INSTR` decimal(2,0) DEFAULT NULL,
    `JOB_DATA` longblob,
    `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
    PRIMARY KEY (`SCHED_NAME`,`TRIGGER_NAME`,`TRIGGER_GROUP`) USING BTREE,
    KEY `IDX_QRTZ_T_C` (`SCHED_NAME`,`CALENDAR_NAME`) USING BTREE,
    KEY `IDX_QRTZ_T_G` (`SCHED_NAME`,`TRIGGER_GROUP`) USING BTREE,
    KEY `IDX_QRTZ_T_J` (`JOB_NAME`,`JOB_GROUP`,`SCHED_NAME`) USING BTREE,
    KEY `IDX_QRTZ_T_JG` (`SCHED_NAME`,`JOB_GROUP`) USING BTREE,
    KEY `IDX_QRTZ_T_NEXT_FIRE_TIME` (`NEXT_FIRE_TIME`,`SCHED_NAME`) USING BTREE,
    KEY `IDX_QRTZ_T_NFT_MISFIRE` (`SCHED_NAME`,`MISFIRE_INSTR`,`NEXT_FIRE_TIME`) USING BTREE,
    KEY `IDX_QRTZ_T_NFT_ST` (`NEXT_FIRE_TIME`,`TRIGGER_STATE`,`SCHED_NAME`) USING BTREE,
    KEY `IDX_QRTZ_T_NFT_ST_MISFIRE` (`NEXT_FIRE_TIME`,`TRIGGER_STATE`,`SCHED_NAME`,`MISFIRE_INSTR`) USING BTREE,
    KEY `IDX_QRTZ_T_NFT_ST_MISFIRE_GRP` (`TRIGGER_GROUP`,`TRIGGER_STATE`,`NEXT_FIRE_TIME`,`MISFIRE_INSTR`,`SCHED_NAME`) USING BTREE,
    KEY `IDX_QRTZ_T_N_G_STATE` (`TRIGGER_GROUP`,`TRIGGER_STATE`,`SCHED_NAME`) USING BTREE,
    KEY `IDX_QRTZ_T_N_STATE` (`TRIGGER_STATE`,`SCHED_NAME`,`TRIGGER_NAME`,`TRIGGER_GROUP`) USING BTREE,
    KEY `IDX_QRTZ_T_STATE` (`TRIGGER_STATE`,`SCHED_NAME`) USING BTREE,
