) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信额度追加明细表';

DROP TABLE IF EXISTS `rat_bkration_adjust`;

CREATE TABLE `rat_bkration_adjust` (
