  `UPDATE_DATE` datetime DEFAULT NULL,
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `rat_bkration_adjust_detail`;

CREATE TABLE `rat_bkration_adjust_detail` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ADJUST_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ITEM_FLAG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ITEM_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ADJUST_MONEY` decimal(18,2) DEFAULT NULL,
  `MONEY` decimal(18,2) DEFAULT NULL,
  `CREDIT_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `rat_bkration_delay`;

CREATE TABLE `rat_bkration_delay` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `RAT_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信编号',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位代码',
  `RAT_TYPE` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信类型',
  `BEGINDATE` datetime DEFAULT NULL COMMENT '授信开始时间',
  `ENDDATE` datetime DEFAULT NULL COMMENT '授信结束时间',
  `DELAY_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '延期标识',
  `DELAY_DATE` datetime DEFAULT NULL COMMENT '延期时间',
  `MONEY` decimal(18,2) DEFAULT NULL COMMENT '金额',
  `STATUS` decimal(5,0) DEFAULT NULL COMMENT '状态',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信延期表';

DROP TABLE IF EXISTS `rat_bkration_detail`;

CREATE TABLE `rat_bkration_detail` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `RAT_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信主键',
  `ITEM_FLAG` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '品种标识',
  `ITEM_ORDER` decimal(2,0) DEFAULT NULL COMMENT '授信品种排序',
  `ITEM_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信品种',
  `MONEY` decimal(18,2) DEFAULT NULL COMMENT '授信金额',
  `OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '敞口金额',
  `SUPER_DISTRIBUTE_MONEY` decimal(18,2) DEFAULT NULL COMMENT '已分配授信金额',
  `SUPER_DISTRIBUTE_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '已分配授信敞口金额',
  `SUPER_ADD_MONEY` decimal(18,2) DEFAULT NULL COMMENT '追加金额',
  `SUPER_ADD_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '追加敞口金额',
  `ASSURECONDITION` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '担保条件',
  `ASSUREPERCENT` decimal(6,2) DEFAULT NULL COMMENT '保证金比例',
  `INTERESTRATE` decimal(8,6) DEFAULT NULL COMMENT '利率',
  `TOTAL_MONEY_ADD_MONEY` decimal(18,2) DEFAULT NULL COMMENT '总额共享追加金额',
  `TOTAL_MONEY_ADD_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '总额共享追加敞口额度',
  `MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '最高额度',
  `COMP_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '综合额度使用标识',
  `SUPER_ADD_MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '追加最高额度',
  `BOND_MONEY` decimal(18,2) DEFAULT NULL,
  `PROCEDURE_FEE_RATE` decimal(8,6) DEFAULT NULL,
  `PROCEDURE_FEE` decimal(18,2) DEFAULT NULL,
  `CREDIT_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信额度明细表';

DROP TABLE IF EXISTS `rat_bkration_dis`;

CREATE TABLE `rat_bkration_dis` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `RAT_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信编号',
  `RAT_CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原授信单位',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '公司代码',
