  `MONEY` decimal(18,2) DEFAULT NULL COMMENT '授信金额',
  `OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '敞口金额',
  `ISPASSED` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '是否通过',
  `DISTRIBUTE_WAY` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '分配方式',
  `REMARK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `STATUS` decimal(10,0) DEFAULT NULL COMMENT '状态',
  `TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '额度类型',
  `DIS_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '分配编号',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CORP_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '额度使用单位名称',
  `BANK_TYPE_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行类别名称',
  `CORP_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '额度使用单位代码',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信分配信息表';

DROP TABLE IF EXISTS `rat_bkration_dis_detail`;

CREATE TABLE `rat_bkration_dis_detail` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `DIS_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信编号',
  `ITEM_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信品种',
  `ITEM_FLAG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '品种标识',
  `MONEY` decimal(18,2) DEFAULT NULL COMMENT '授信金额',
  `OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '敞口金额',
  `SUPER_PROCESS_MONEY` decimal(18,2) DEFAULT NULL COMMENT '占用金额',
  `SUPER_RELIEF_MONEY` decimal(18,2) DEFAULT NULL COMMENT '调剂金额',
  `SUPER_BY_RELIEF_MONEY` decimal(18,2) DEFAULT NULL COMMENT '被调剂金额',
  `FREEZE_MONEY` decimal(18,2) DEFAULT NULL COMMENT '冻结金额',
  `RELIEF_AND_URATION_MONEY` decimal(18,2) DEFAULT NULL COMMENT '虚拟调剂占用金额',
  `FREEZE_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '冻结敞口金额',
  `SUPER_BY_RELIEF_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '被调剂敞口金额',
  `SUPER_RELIEF_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '调剂敞口金额',
  `SUPER_PROCESS_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '已正式占用金额',
  `VIRTUAL_RELIEF_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '虚拟敞口调剂金额',
  `VIRTUAL_RELIEF_MONEY` decimal(18,2) DEFAULT NULL COMMENT '虚拟调剂金额',
  `VIRTUAL_URATION` decimal(18,2) DEFAULT NULL COMMENT '虚拟占用金额',
  `URATION_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '虚拟调剂敞口占用金额',
  `ITEM_ORDER` decimal(2,0) DEFAULT NULL COMMENT '品种排序',
  `MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '最高额度',
  `VIRTUAL_OPEN_URATION` decimal(18,2) DEFAULT NULL COMMENT '虚拟敞口占用金额',
  `PROCESS_MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '占用最高额度',
  `RELIEF_MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '调剂最高额度',
  `BY_RELIEF_MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '被调剂最高额度',
  `FREEZE_MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '冻结最高额度',
  `COMP_SIGN` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '综合额度使用标识',
  `VIRTUAL_MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '虚拟占用最高额度',
  `CREDIT_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信分配明细表';

DROP TABLE IF EXISTS `rat_bkration_relief`;

CREATE TABLE `rat_bkration_relief` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `RAT_TYPE` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信种类',
  `REF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂编号',
  `RAT_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信编号',
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位代码',
  `CUR_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币种',
  `RELIEF_CORP` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂单位',
  `RELIEF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂额度编号',
  `RELIEF_ITEM_FLAG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂品种标识',
  `RELIEF_ITEM_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂品种',
  `BY_RELIEF_CORP` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '被调剂单位',
  `BY_RELIEF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '被调剂额度编号',
  `BY_RELIEF_ITEM_FLAG` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '被调剂品种标识',
  `BY_RELIEF_ITEM_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '被调剂品种',
  `RELIEF_MONEY` decimal(18,2) DEFAULT NULL COMMENT '被调剂金额',
  `RELIEF_OPEN_MONEY` decimal(18,2) DEFAULT NULL COMMENT '敞口金额',
  `BEGINDATE` datetime DEFAULT NULL COMMENT '开始日期',
  `STATUS` decimal(6,0) DEFAULT NULL COMMENT '状态',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ATTACHMENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RELIEF_CORP_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂单位名称',
  `BY_RELIEF_CORP_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '被调剂单位名称',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信额度调剂表';

DROP TABLE IF EXISTS `rat_bkration_relief_detail`;

CREATE TABLE `rat_bkration_relief_detail` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `REF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂表ID',
  `REF_TYPE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂类型',
  `RELIEF_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂授信编号',
  `ITEM_FLAG` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调剂品种标识',
  `ITEM_ORDER` decimal(5,0) DEFAULT NULL COMMENT '授信品种排序',
  `RELIEF_ITEM_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信品种',
  `RELIEF_MAX_MONEY` decimal(18,2) DEFAULT NULL COMMENT '调剂最高额度',
  `RELIEF_MONEY` decimal(18,2) DEFAULT NULL COMMENT '实际调剂额度',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信调剂明细表';

DROP TABLE IF EXISTS `rat_business_race`;

CREATE TABLE `rat_business_race` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `custom_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `race_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `rat_credit_cooperation_bank`;

CREATE TABLE `rat_credit_cooperation_bank` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `BANK_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '开户行行号',
  `BANK_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '开户行名称',
  `COOPERATION_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信银行合作情况：0-未合作、1-已合作、2-计划合作',
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '修改人',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '修改时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信合作银行维护表';

DROP TABLE IF EXISTS `rat_credit_type`;

CREATE TABLE `rat_credit_type` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '额度类型编码',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '额度类型名称',
  `STATUS` decimal(2,0) DEFAULT NULL COMMENT '状态',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='授信额度类型';

DROP TABLE IF EXISTS `rat_item_custom`;

CREATE TABLE `rat_item_custom` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '授信品种编码',
  `NAME` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '授信品种名称',
  `FLAG` decimal(10,0) DEFAULT NULL COMMENT '综合标志',
  `TYPE` decimal(10,0) DEFAULT NULL COMMENT '品种类型',
