DROP TABLE IF EXISTS `raw_data`;

CREATE TABLE `raw_data` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `DATA_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据名称:供应商、子企业、机构或者其他的数据名称',
  `DATA_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据代码',
  `ESTABLISHMENT_DATE` date DEFAULT NULL COMMENT '成立时间(yyyy-MM-dd)',
  `REGISTERED_CAPITAL` decimal(15,2) DEFAULT NULL COMMENT '注册资本',
  `LEGAL_REPRESENTATIVE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '法定代表人',
  `BUSINESS_SCOPE` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '经营范围',
  `DATA_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据来源业务表主建(供应商、子企业、机构的主键)',
  `DATA_SOURCE_CATEGORY_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据来源类别名称;数据来源(Data_Source)Data_Source_Category_Name',
  `DATA_SOURCE_CATEGORY_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据来源类别代码;数据来源(Data_Source)Data_Source_Category_Code.D001 供应商',
  `DATA_SOURCE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外键(数据来源主键);数据来源(Data_Source)主键 id',
  `CREATOR` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '创建人',
  `CREATE_DATE` date NOT NULL COMMENT '创建日期时间:yyyy-MM-dd hh24:mm:ss',
  `ATTACHMENT_ID` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件id',
  `STATUS` int DEFAULT '0' COMMENT '状态：-2 已删除;95 正常;默认为 0',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='原始数据';

DROP TABLE IF EXISTS `scoring_grade`;

CREATE TABLE `scoring_grade` (
  `ID` varchar(32) NOT NULL COMMENT '主键',
  `SCORING_GRADE_NAME` varchar(100) DEFAULT NULL COMMENT '评级名称',
