  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期时间',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='评分等级';

DROP TABLE IF EXISTS `scoring_grade_fix_report`;

CREATE TABLE `scoring_grade_fix_report` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `EVALUATION_REPORT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评估报告主键 评估报告（EVALUATION_REPORT）id',
  `MODEL_BATCH_NUMBER` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '模型批次号 模型批次的批次号',
  `EVALUATION_BATCH_NUMBER` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评估批次号',
  `MODEL_SOLIDIFICATION_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外键（报告中计算模型固化主键） 计算模型固化（MODEL_SOLIDIFICATION_FOR_REPORT）id',
  `SCORING_SYSTEM` decimal(10,0) DEFAULT NULL COMMENT '计分制 用于确定评分等级的具体规则和方法',
  `SCORING_GRADE_DESCRIPTION` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分等级说明 提供了对每个评分等级含义的详细解释,包括达到该等级所需满足的条件或标准',
  `INSTITUTION_TYPE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '机构类别',
  `SCORING_GRADE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评级名称',
  `SCORING_GRADE_CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评级编码',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报告中评分等级固化 计算模型中的评分等级.指的是将评分结果划分为不同的级别或类别';

DROP TABLE IF EXISTS `scoring_grade_le_fix_report`;

CREATE TABLE `scoring_grade_le_fix_report` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `EVALUATION_REPORT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评估报告主键 评估报告（EVALUATION_REPORT）id',
  `MODEL_BATCH_NUMBER` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '模型批次号 模型批次的批次号',
  `EVALUATION_BATCH_NUMBER` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评估批次号',
  `SCORING_GRADE_FIX_REPORT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外键（报告中评分等级固化主键） 评分等级固（SCORING_GRADE_FIX_REPORT）id',
  `MODEL_SOLIDIFICATION_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '计算模型固化主键 计算模型固化（MODEL_SOLIDIFICATION）id',
  `SCORING_LEVEL` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分级别 一个具体等级,它通常由一个特定的分数范围定义.例如AAA、AA、A、BBB等',
  `UPPER_SCORE_LIMIT_LEVEL` int DEFAULT NULL COMMENT '评分级别上限分 能够达到该评分级别的最高分数',
  `LOWER_SCORE_LIMIT_LEVEL` int DEFAULT NULL COMMENT '评分级别下线分 能够达到该评分级别的最低分数',
  `EXPLANATION_OF_SCORING_LEVEL` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分级别说明  提供了关于每个评分级别的详细解释,包括该级别的意义、如何达到该级别以及该级别的具体标准',
  `UP_SCORING_SYMBOL` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '上限等级符号',
  `DOWN_SCORING_SYMBOL` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '下限等级符号',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报告中评分等级级别固化 计算模型中的一部分,指的是评分中不同等级或层次,通常按照分数或表现的不同将评分分为几个等级';

