DROP TABLE IF EXISTS `scoring_indicator_fix_report`;

CREATE TABLE `scoring_indicator_fix_report` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `MODEL_SOLIDIFICATION_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外键（报告中计算模型固化主键） 计算模型固化（MODEL_SOLIDIFICATION_REPORT）id',
  `EVALUATION_REPORT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评估报告主键 评估报告（EVALUATION_REPORT）id',
  `MODEL_BATCH_NUMBER` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '模型批次号 模型批次的批次号',
  `EVALUATION_BATCH_NUMBER` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评估批次号',
  `SCORING_INDICATOR_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标名称 评分指标的名称',
  `SCORING_INDICATOR_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标代码 评分指标的代码',
  `SCORING_INDICATOR_DESCRIPTION` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标说明 评分指标作用说明',
  `SCORING_INDICATOR_COEFFICIENT` decimal(8,6) DEFAULT NULL COMMENT '评分指标系数 分配给每个评分指标的重要性权重',
  `CATEGORY_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指标类别名称 冗余.指标类别表（INDICATOR_CATEGORY）属性CATEGORY_NAME',
  `CATEGORY_ENCODING` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指标类别代码 冗余.指标类别表（INDICATOR_CATEGORY）属性CATEGORY_ENCODING',
  `I_C_F_R_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '报告中指标类别固化主键 报告中指标类别固化（INDICATOR_CATEGORY_FIX_REPORT）的主键',
  `VERSION_NUMBER` decimal(10,0) DEFAULT NULL COMMENT '版本号',
  `DATA_SOURCE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据源id',
  `DATA_SOURCE_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据源代码',
  `DATA_SOURCE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据源名称',
  `DATA_SOURCE_ORIGIN` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据源取值来源',
  `LEVEL_` decimal(4,0) DEFAULT NULL COMMENT '指标级别',
