  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报告中评分指标固化  评估报告完成后,计算模型选定的评分指标,将其固化到本表中';

DROP TABLE IF EXISTS `scoring_indicator_solidificati`;

