  `SCORING_INDICATOR_CODE` varchar(15) DEFAULT NULL,
  `SCORING_INDICATOR_DESCRIPTION` varchar(200) DEFAULT NULL COMMENT '评分指标说明',
  `SCORING_INDICATOR_COEFFICIENT` decimal(8,6) DEFAULT NULL COMMENT '评分指标系数',
  `CATEGORY_NAME` varchar(100) DEFAULT NULL COMMENT '指标类别名称',
  `CATEGORY_ENCODING` varchar(4) DEFAULT NULL COMMENT '指标类别代码',
  `PARENT_ID` varchar(32) DEFAULT NULL COMMENT '指标类别固化id',
  `LEVEL_` decimal(4,0) DEFAULT NULL COMMENT '指标级别',
  `SCORINGRUBRIC` varchar(1000) DEFAULT NULL COMMENT '评分细则标题',
  `CREATOR` varchar(100) DEFAULT NULL COMMENT '创建人',
  `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建日期时间',
  `DATA_SOURCE_ID` varchar(32) DEFAULT NULL COMMENT '数据源id',
  `DATA_SOURCE_CODE` varchar(32) DEFAULT NULL COMMENT '数据源code',
  `DATA_SOURCE_NAME` varchar(100) DEFAULT NULL COMMENT '数据源名称',
  `DATA_SOURCE_ORIGIN` varchar(1000) DEFAULT NULL COMMENT '数据源取值来源',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='评分指标固化';

DROP TABLE IF EXISTS `scoring_indicator_value`;

CREATE TABLE `scoring_indicator_value` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `SCORING_INDICATOR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标主键:评分指标(Scoring_Indicator)id',
  `SCORING_INDICATOR_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标名称',
  `SCORING_INDICATOR_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标代码',
  `SCORING_INDICATOR_DESCRIPTION` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标说明',
  `CATEGORY_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指标类别名称;冗余.指标类别表(Indicator_Category)属性Category_Name',
  `CATEGORY_ENCODING` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指标类别代码;冗余.指标类别表(Indicator_Category)属性Category_Encoding',
  `INDICATOR_VALUE` decimal(15,2) DEFAULT NULL COMMENT '指标数值：待评数据指标的数值',
  `VERSION_NUMBER` int DEFAULT NULL COMMENT '版本号',
  `INSTITUTIONAL_RAW_DATA_ID` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外键(原始数据主键)：原始数据(Raw_Data)id',
  `CREATOR` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '创建人',
  `CREATE_DATE` date NOT NULL COMMENT '创建日期时间:yyyy-MM-dd hh24:mm:ss',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='评分指标数值';

DROP TABLE IF EXISTS `scoring_metric_val_fix_report`;

CREATE TABLE `scoring_metric_val_fix_report` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `SCORING_INDICATOR_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标名称 评分指标的名称',
  `SCORING_INDICATOR_CODE` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标代码 评分指标的代码',
  `SCORING_INDICATOR_DESCRIPTION` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评分指标说明 评分指标作用说明',
  `CATEGORY_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '标类别名称 冗余.指标类别表（INDICATOR_CATEGORY）属性CATEGORY_NAME',
  `CATEGORY_ENCODING` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '指标类别代码 冗余.指标类别表（INDICATOR_CATEGORY）属性CATEGORY_ENCODING',
  `INDICATOR_VALUE` decimal(19,6) DEFAULT NULL COMMENT '指标数值 待评数据指标的数值',
  `EVALUATED_DATA_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '外键（报告中已评数据主键） 已评数据（EVALUATED_DATA_FOR_REPORT）id',
  `SCORE` decimal(15,2) DEFAULT NULL COMMENT '指标得分',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报告中评分指标数值固化  评分指标值,用于存放已评数据评分指标的数值';

DROP TABLE IF EXISTS `sys_account_grant`;

CREATE TABLE `sys_account_grant` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ACCOUNT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '内部帐号或者银行帐号',
  `ACCOUNT_TYPE` decimal(1,0) DEFAULT NULL,
  `USER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CAN_QUERY_DETAIL` decimal(1,0) DEFAULT NULL COMMENT '是否可查看明细',
  `CAN_QUERY_BALANCE` decimal(1,0) DEFAULT NULL COMMENT '是否可查询余额',
  `CAN_TRANSFER_ACCOUNTS` decimal(1,0) DEFAULT NULL COMMENT '是否可转账',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_SYS_ACCOUNT_GRANT` (`ACCOUNT_ID`,`USER_ID`) USING BTREE,
  KEY `IDX_SYS_ACCOUNT_GRANT_UI_CQD` (`USER_ID`,`CAN_QUERY_DETAIL`,`ACCOUNT_ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `sys_account_grant_his`;

CREATE TABLE `sys_account_grant_his` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ACCOUNT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '内部帐号或者银行帐号',
  `ACCOUNT_TYPE` decimal(1,0) DEFAULT NULL,
  `USER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CAN_QUERY_DETAIL` decimal(1,0) DEFAULT NULL COMMENT '是否可查看明细',
  `CAN_QUERY_BALANCE` decimal(1,0) DEFAULT NULL COMMENT '是否可查询余额',
  `CAN_TRANSFER_ACCOUNTS` decimal(1,0) DEFAULT NULL COMMENT '是否可转账',
  `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新人ID',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='帐号授权历史表';

DROP TABLE IF EXISTS `sys_account_mapping`;

CREATE TABLE `sys_account_mapping` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `SYS_USER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '系统用户id',
  `RELATION_USER_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '其他平台用户id',
  `CLIENT_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '账号映射类型:0-微信 1-钉钉',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='用户账号映射关系表';

DROP TABLE IF EXISTS `sys_api_server_config`;

CREATE TABLE `sys_api_server_config` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '服务名称',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '服务编码',
  `type` tinyint DEFAULT NULL COMMENT '参数类型：1 xml，2 json',
  `request_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '请求地址',
  `channel_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '渠道号',
  `status` tinyint DEFAULT NULL COMMENT '启用状态：1 启用，0 未启用',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='Api网关接口服务配置';

DROP TABLE IF EXISTS `sys_article`;

CREATE TABLE `sys_article` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `TITLE` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CONTEXT` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `ATTACHMENT_ID` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_TOP` int DEFAULT NULL,
  `TYPE` int DEFAULT NULL,
  `RECEIVER_TYPE` int DEFAULT NULL,
  `STATUS` int DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `sys_article_role`;

CREATE TABLE `sys_article_role` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ARTICLE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ROLE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `sys_article_user`;

CREATE TABLE `sys_article_user` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `ARTICLE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '公告ID',
  `USER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '用户ID',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='用户公告表';

DROP TABLE IF EXISTS `sys_article_user_his`;

CREATE TABLE `sys_article_user_his` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `ARTICLE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '公告ID',
  `USER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '用户ID',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='用户公告历史表';

DROP TABLE IF EXISTS `sys_attachment`;

CREATE TABLE `sys_attachment` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'id',
  `USER_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用户ID',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件名称',
  `RE_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件别名',
  `TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件类型',
  `SUFFIX` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件后缀',
  `FILE_SIZE` decimal(10,2) DEFAULT NULL COMMENT '附件大小',
  `PATH` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '附件地址',
  `DESCRIPTION` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件描述',
  `CATEGORY` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '附件分类',
  `STATUS` decimal(2,0) DEFAULT NULL COMMENT '状态',
  `GROUP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '组别id',
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='附件表';

DROP TABLE IF EXISTS `sys_black_white_list`;

CREATE TABLE `sys_black_white_list` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NAME` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `BW_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `LIST_TYPE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CORP_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `IS_COMMON` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `DATA_SOURCES` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `COUNTRY_ID` varchar(65) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `VALID_SIGN` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `EXTERNAL_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RMK` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `sys_ca_info`;

CREATE TABLE `sys_ca_info` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ENCRY_DATE` datetime NOT NULL COMMENT '产生编码日期',
  `RANDOM` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '加密随机数',
  `ENCRY_SOURCE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '编码源',
  `CA_CODING` longblob COMMENT 'CA编码',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='CA信息表';

DROP TABLE IF EXISTS `sys_calendar`;

CREATE TABLE `sys_calendar` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `CALENDAR_NUM` decimal(14,0) NOT NULL,
  `WORK_DAY_SIGN` decimal(6,0) NOT NULL,
  `MONTH_END_SIGN` decimal(6,0) NOT NULL,
  `YEAR_END_SIGN` decimal(6,0) NOT NULL,
  `CREATE_DATE` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `COUNTRY_ID` varchar(65) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `sys_config`;

CREATE TABLE `sys_config` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置类型',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置名',
  `VALUE` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置值',
  `CHANGE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `TYPE` (`TYPE`,`NAME`,`TENANT_ID`),
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='系统参数配置';

DROP TABLE IF EXISTS `sys_config_back`;

CREATE TABLE `sys_config_back` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置类型',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置名',
  `VALUE` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置值',
  `CHANGE` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

DROP TABLE IF EXISTS `sys_config_log`;

CREATE TABLE `sys_config_log` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置类型',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置名',
  `BEFORE_VALUE` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调整前参数值',
  `AFTER_VALUE` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '调整后参数值',
  `UPDATE_DATE` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='系统参数日志表';

DROP TABLE IF EXISTS `sys_corp`;

CREATE TABLE `sys_corp` (
  `ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ACCOUNT_LICENCE` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `ADDRESS` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CITY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `COLLECT_FLAG` decimal(10,0) DEFAULT NULL COMMENT 'collectFlag',
  `CTL_BUDGET` decimal(10,0) DEFAULT NULL,
  `HEAD_PERSON` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `LISTED_COMPANY` decimal(10,0) NOT NULL COMMENT 'listedCompany',
  `NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PARENT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `PARENT_IDS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `PROVINCE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SORT` decimal(10,0) DEFAULT NULL COMMENT 'sort',
  `STATUS` decimal(10,0) NOT NULL COMMENT 'status',
  `TYPE` decimal(10,0) DEFAULT NULL,
  `USE_ACCOUNT_CODE` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `NET_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `RAT_GROUP` decimal(1,0) DEFAULT NULL COMMENT '集团统一授信主体',
  `CREATE_TIME` datetime DEFAULT NULL,
  `CREATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
