  `ADDRESS_EN` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CUR_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UNIT_ATTRIBUTE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `UNIT_CM` varchar(10000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `COUNTRY_ID` varchar(65) COLLATE utf8mb4_bin DEFAULT NULL,
  `CERT_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `CERT_NO` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `SOC_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '缁熶竴绀句細淇＄敤浠ｇ爜',
  `operationArea_ID` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '营运区维护编码',
  `equityMaintenance_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '股权维护Id',
  `unitStoreMaintenance_ID` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位仓库维护Id',
  `PROVINCE_ID` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '省区id',
  `REPORT_DISPLAY` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '1' COMMENT '报表是否显示：1-是，0-否',
  `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`ID`) USING BTREE,
