) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `sys_corp_to_login_name`;

CREATE TABLE `sys_corp_to_login_name` (
