  KEY `IDX_S_CORP_USER_RESOUR_MUCP` (`MENU_ID`,`USER_ID`,`CORP_ID`,`PERMISSION`) USING BTREE,
  KEY `IDX_SYS_CORP_USER_RESOURCE_UPC` (`USER_ID`,`PERMISSION`,`CORP_ID`) USING BTREE,
  KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `sys_country_cust`;

